/// Lines every 100 ms for 3 seconds, then none for ten minutes.
fn listen_burst() -> String {
    let line = |n: usize| format!(r#"{{"after_ms":100,"from":"them","text":"made-up line {n}","final":true}}"#);
    let mut text: Vec<String> = (0..30).map(line).collect();
    text.push(r#"{"after_ms":600000,"from":"them","text":"never heard","final":true}"#.into());
    text.join("\n")
}

#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_replys_seq_and_frame_rise_the_same_whether_someone_speaks_or_not() {
    let otto = listen_otto_with("seq", &listen_burst(), r#"{"repos": [], "restore_layout": false}"#);
    otto.call(json!({"cmd": "split"}));
    otto.user_key("cmd-ctrl-t");
    otto.listen_finals(1);
    // How far `seq` and `frame.number` move in 2 seconds.
    let rise = || {
        let at = |o: &Otto| {
            let frame = o.call(json!({"cmd": "state"}))["frame"].clone();
            (frame["seq"].as_u64().unwrap(), frame["number"].as_u64().unwrap())
        };
        let before = at(&otto);
        std::thread::sleep(Duration::from_secs(2));
        let after = at(&otto);
        (after.0 - before.0, after.1 - before.1)
    };
    // While lines come: about 20 of them.
    let speaking = rise();
    let heard = otto.listen_finals(30).as_array().unwrap().len();
    assert_eq!(heard, 30);
    let silent = rise();
    // One dispatch per line would add 20; a batch per tick adds none. A tick's jitter is the slack.
    assert!(speaking.0.abs_diff(silent.0) <= 2, "seq rose {} speaking, {} silent", speaking.0, silent.0);
    assert!(speaking.1.abs_diff(silent.1) <= 3, "frames rose {} speaking, {} silent", speaking.1, silent.1);
    assert!(silent.0 >= 6, "a batch every tick, even empty: {silent:?}");
}

impl Otto {
    /// The transcript's label, by its id in `listen_rects` (`speech`, `sound`, `silent`), once it says `want`.
    fn listen_hearing(&self, want: &str) {
        self.wait_for(&format!("the label to say {want}"), |o| {
            let drawn = o.drawn();
            drawn["listen_rects"].get(format!("listen-hearing:{want}")).map(|_| ())
        });
    }
}

#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn the_drawer_shows_it_hears_speech_then_sound_then_nothing_and_no_reply_says_so() {
    // Words for 6 s, so a slow first look still finds them; one level, then quiet.
    let words = (0..20).map(|n| format!(r#"{{"after_ms":300,"from":"them","text":"made-up {n}","final":false}}"#));
    let fixture = std::iter::once(r#"{"after_ms":100,"level":0.3}"#.to_string())
        .chain(words)
        .chain([r#"{"after_ms":600000,"from":"them","text":"never heard","final":true}"#.to_string()])
        .collect::<Vec<_>>()
        .join("\n");
    let fixture = fixture.as_str();
    let otto = listen_otto_with("hearing", fixture, r#"{"repos": [], "restore_layout": false}"#);
    otto.call(json!({"cmd": "split"}));
    otto.user_key("cmd-ctrl-t");
    otto.listen_hearing("speech");
    otto.listen_rect("listen-header:1");
    // Words stop, sound was there: listening. What it hears is never in a reply's state.
    otto.listen_hearing("sound");
    let mut state = otto.call(json!({"cmd": "state"}));
    state["listen_lines"] = Value::Null;
    state["listen_rects"] = Value::Null;
    let text = state.to_string();
    assert!(!text.contains("Hearing") && !text.contains("Listening"), "{text}");
    // 30 s without sound: the label says so.
    std::thread::sleep(Duration::from_secs(29));
    otto.listen_hearing("silent");
}

#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_lost_stream_greys_the_dot_and_the_bar_says_why_until_the_user_puts_it_away() {
    let otto = listen_otto("lost");
    otto.call(json!({"cmd": "split"}));
    otto.user_key("cmd-ctrl-t");
    otto.listen_finals(1);
    let lost = otto.call(json!({"cmd": "listen_end", "why": "stream_failed"}));
    assert_eq!(
        (&lost["state"]["listen"], &lost["notice"]),
        (&Value::Null, &json!("Transcript stopped: the sound stopped coming"))
    );
    let grey = otto.listen_rect("listen-lost");
    let header = rect(&otto.drawn()["headers"]["1"]);
    assert!(grey[1] >= header[1] && grey[1] < header[1] + header[3], "{grey:?} in {header:?}");
    // A client's click on its × does nothing; the user's puts it away.
    let close = otto.listen_rect("listen-stop:lost");
    otto.call(json!({"cmd": "mouse", "action": "down", "x": close[0] + 2.0, "y": close[1] + 2.0}));
    otto.call(json!({"cmd": "mouse", "action": "up", "x": close[0] + 2.0, "y": close[1] + 2.0}));
    assert!(otto.drawn()["listen_rects"].get("listen-lost").is_some());
    otto.user_click(at(close, 0.5, 0.5));
    let drawn = otto.drawn();
    assert!(drawn["listen_rects"].get("listen-lost").is_none(), "{}", drawn["listen_rects"]);
    assert!(
        drawn["listen_rects"].get("listen-start:1").is_some(),
        "it offers a start again: {}",
        drawn["listen_rects"]
    );
}

/// ⌘ tapped twice, alone, returns as the return key does; ⌘C then ⌘, or a slow pair, does not.
/// The changes are made up (`modifier_flags`): a test run listens to no keyboard.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_double_tap_of_cmd_returns_and_a_shortcut_does_not() {
    let otto = Otto::launch("double-cmd");
    let send = |changes: Value| {
        otto.call(json!({"cmd": "modifier_flags", "changes": changes}))["counts"]["double_cmds"].clone()
    };
    // ⌘C (a key down while ⌘ is), then a tap; then two taps 500 ms apart.
    let shortcut = json!([{"at": 0, "cmd": true}, {"at": 90, "cmd": false, "input_at": 40}, {"at": 200, "cmd": true}, {"at": 260, "cmd": false, "input_at": 40}]);
    assert_eq!(send(shortcut), 0);
    let slow = json!([{"at": 1000, "cmd": true}, {"at": 1080, "cmd": false}, {"at": 1580, "cmd": true}, {"at": 1650, "cmd": false}]);
    assert_eq!(send(slow), 0);
    let double = json!([{"at": 3000, "cmd": true}, {"at": 3080, "cmd": false}, {"at": 3200, "cmd": true}, {"at": 3270, "cmd": false}]);
    assert_eq!(send(double), 1);
}

/// A change of the displays (a laptop taken off its monitors) has the shell kick GPUI to draw
/// again, by GPUI's own `windowDidChangeScreen:` and `displayLayer:`, and the window goes on
/// drawing after it. A test cannot unplug a display, so its display link never breaks here:
/// this proves the kicks happen, as planned, and draw, not that they mend a broken link.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn the_window_draws_on_after_the_displays_change() {
    let otto = Otto::launch("display-change");
    let redraws = |o: &Otto| o.call(json!({"cmd": "state"}))["counts"]["redraws"].as_u64().expect("redraws");
    assert_eq!(redraws(&otto), 0, "a window that draws is not kicked");
    otto.call(json!({"cmd": "display_change"}));
    // At once, then as the new setup settles: four within 3 s.
    let kicked = otto.wait_for("the kicks after the change", |o| Some(redraws(o)).filter(|n| *n >= 4));
    for _ in 0..3 {
        let before = otto.call(json!({"cmd": "state"}))["frame"]["number"].as_u64().expect("frame");
        let after = otto.call(json!({"cmd": "split", "axis": "down"}));
        let drawn = after["frame"]["number"].as_u64().expect("frame");
        assert!(drawn > before && after["stale"].is_null(), "{before} {after}");
    }
    // Frames come, so nothing more is kicked.
    assert_eq!(redraws(&otto), kicked);
}

/// `OTTOSPACE_E2E_WINDOW` sizes a test run's window: CI's, 1024x674, on a larger screen. One asked
/// larger than every screen is kept no larger than the screen it is on, as 1400x900 is on CI's.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_test_runs_window_is_the_size_asked_and_no_larger_than_its_screen() {
    let otto = Otto::launch_with("window-size", &[("OTTOSPACE_E2E_WINDOW", "1024x674")]);
    let window = rect(&otto.call(json!({"cmd": "state"}))["window"]);
    assert_eq!((window[2], window[3]), (1024., 674.), "{window:?}");
    drop(otto);
    let env = [("OTTOSPACE_E2E_WINDOW", "8000x8000"), ("OTTOSPACE_FEATURES", "multi_monitor")];
    let otto = Otto::launch_with("window-huge", &env);
    let displays = otto.wait_for("the real displays", |o| {
        let state = o.call(json!({"cmd": "state"}));
        Some(state["displays"].clone()).filter(|d| d.as_array().is_some_and(|d| !d.is_empty()))
    });
    let window = rect(&otto.call(json!({"cmd": "state"}))["window"]);
    let largest = |at: usize| {
        displays.as_array().into_iter().flatten().filter_map(|d| d["frame"][at].as_f64()).fold(0., f64::max)
    };
    assert!(window[2] <= largest(2) && window[3] <= largest(3), "{window:?} on {displays}");
}

/// The state lists the displays by place, the main window's marked, never a uid. A test's
/// made-up ones stand for them, in screen order; one left out is unplugged.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn the_state_lists_the_displays_and_a_test_makes_them_up() {
    let otto = Otto::launch_with("displays", &[("OTTOSPACE_FEATURES", "multi_monitor")]);
    let real = otto.wait_for("the real displays", |o| {
        let state = o.call(json!({"cmd": "state"}));
        Some(state["displays"].clone()).filter(|d| d.as_array().is_some_and(|d| !d.is_empty()))
    });
    let mains = real.as_array().iter().flat_map(|d| d.iter()).filter(|d| d["main"] == true).count();
    assert_eq!(mains, 1, "{real}");
    let left = json!({"uid": "left", "frame": [-1920, 0, 1920, 1080], "scale": 1});
    let built_in = json!({"uid": "built-in", "frame": [0, 0, 1728, 1117]});
    let state = otto.call(json!({"cmd": "displays_set", "displays": [built_in, left], "main": "built-in"}));
    let expected = json!([
        {"id": 0, "frame": [-1920.0, 0.0, 1920.0, 1080.0], "scale": 1.0, "main": false},
        {"id": 1, "frame": [0.0, 0.0, 1728.0, 1117.0], "scale": 2.0, "main": true},
    ]);
    assert_eq!((&state["displays"], &state["out"]), (&expected, &json!([])), "{state}");
    assert!(!state.to_string().contains("built-in"), "no uid in the state");
    let state = otto.call(json!({"cmd": "displays_set", "displays": [built_in]}));
    assert_eq!(state["displays"].as_array().map(Vec::len), Some(1));
}

/// ⌘⇧O folds the tab on show out to the other display, in a window of its own that draws its
/// panes, the keyboard with it; ⌘T there acts on the main window. Its tab in the main window's row
/// folds it back in; so does unplugging the display, and plugging it in again takes it back.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_tab_folds_out_to_another_display_and_back_in() {
    let otto = Otto::launch_with("tab-out", &[("OTTOSPACE_FEATURES", "multi_monitor")]);
    // The real screens: macOS keeps a window no wider than the one it is on (CI's is 1024 wide).
    let real = otto.wait_for("the real displays", |o| {
        let state = o.call(json!({"cmd": "state"}));
        Some(state["displays"].clone()).filter(|d| d.as_array().is_some_and(|d| !d.is_empty()))
    });
    let main = json!({"uid": "main", "frame": [0, 0, 1728, 1117]});
    let other = json!({"uid": "other", "frame": [1728, 0, 1920, 1080], "scale": 1});
    otto.call(json!({"cmd": "displays_set", "displays": [main, other], "main": "main"}));
    // A workspace of two tabs, a terminal in each; the second on show.
    otto.call(json!({"cmd": "split"}));
    otto.call(json!({"cmd": "new_tab"}));
    let state = otto.call(json!({"cmd": "split"}));
    let tabs = &state["state"]["tabs"];
    let (first, second) = (tabs[0]["id"].as_u64().unwrap(), tabs[1]["id"].as_u64().unwrap());
    // A client's ⌘⇧O is refused: only the user folds a tab out.
    let refused = otto.call(json!({"cmd": "key", "keys": "cmd-shift-o"}));
    assert_eq!(refused["out"], json!([]), "{refused}");
    let state = otto.call(json!({"cmd": "key", "keys": "cmd-shift-o", "as": "user"}));
    assert_eq!(state["out"], json!([{"tab": second, "display": 1}]), "{state}");
    // The main window shows the workspace's other tab; the keyboard went with the tab.
    let windows = &state["windows"];
    assert_eq!((&windows[0]["tab"], &windows[0]["key"]), (&json!(first), &json!(false)), "{windows}");
    assert_eq!((&windows[1]["tab"], &windows[1]["key"]), (&json!(second), &json!(true)), "{windows}");
    // Its window opens and draws, the made-up display's width, or the real screen's it sits on if
    // narrower (macOS keeps it no larger than the screen).
    let frame = otto.wait_for("the tab out's window", |o| {
        let state = o.call(json!({"cmd": "state"}));
        let window = &state["windows"][1];
        window["frames"].as_u64().is_some_and(|n| n > 0).then(|| window["frame"].clone())
    });
    let x = frame[0].as_f64().expect("x");
    let screen = real.as_array().into_iter().flatten().find(|d| {
        let (left, w) = (d["frame"][0].as_f64().unwrap_or(0.), d["frame"][2].as_f64().unwrap_or(0.));
        (left..left + w).contains(&x)
    });
    let screen_w = screen.and_then(|d| d["frame"][2].as_f64()).expect("the window on a real screen");
    assert_eq!(frame[2].as_f64(), Some(screen_w.min(1920.)), "{frame} {real}");
    // Typed keys reach its terminal.
    otto.call(json!({"cmd": "type", "text": "echo out-$((6*7))\r"}));
    let pane = state["state"]["focused"].as_u64().unwrap();
    otto.call(json!({"cmd": "wait", "pane": pane, "pattern": "^out-42$"}));
    // Its tab in the main window's row is marked out, with Fold back in.
    otto.control(&format!("tab-in:{second}"));
    // ⌘T there opens a tab in the main window's workspace, the keyboard with it.
    let state = otto.call(json!({"cmd": "key", "keys": "cmd-t", "as": "user"}));
    assert_eq!(state["out"], json!([{"tab": second, "display": 1}]));
    assert_eq!(state["windows"][0]["key"], json!(true), "{state}");
    let made = state["windows"][0]["tab"].clone();
    assert!(made != json!(first) && made != json!(second), "{state}");
    // Fold back in, from the main window's row: a client's click is refused; the user's closes the
    // window, and the main window keeps its tab.
    let [x, y, w, h] = otto.control(&format!("tab-in:{second}"));
    let state = otto.click([x + w / 2., y + h / 2.], 1);
    assert_eq!(state["out"], json!([{"tab": second, "display": 1}]), "{state}");
    let state = otto.user_click([x + w / 2., y + h / 2.]);
    assert_eq!(state["out"], json!([]), "{state}");
    assert_eq!(state["windows"].as_array().map(Vec::len), Some(1), "{state}");
    assert_eq!(state["windows"][0]["tab"], made);
    // Out again, then the display unplugged: folded in. Plugged in again: back out.
    otto.call(json!({"cmd": "select_tab", "index": 1}));
    otto.call(json!({"cmd": "key", "keys": "cmd-shift-o", "as": "user"}));
    let state = otto.call(json!({"cmd": "displays_set", "displays": [main], "main": "main"}));
    assert_eq!((&state["out"], &state["windows"][0]["key"]), (&json!([]), &json!(true)), "{state}");
    let state = otto.call(json!({"cmd": "displays_set", "displays": [main, other], "main": "main"}));
    assert_eq!(state["out"], json!([{"tab": second, "display": 1}]), "{state}");
    otto.wait_for("the window back", |o| {
        let state = o.call(json!({"cmd": "state"}));
        state["windows"][1]["frames"].as_u64().filter(|n| *n > 0)
    });
}

/// The only tab of a workspace folded out: an empty tab of the workspace stands in for it in the
/// main window (its empty state, not Home). Folded back in, the tab takes its place again.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn the_only_tab_folded_out_leaves_an_empty_tab_until_it_folds_back_in() {
    let otto = Otto::launch_with("tab-out-alone", &[("OTTOSPACE_FEATURES", "multi_monitor")]);
    let main = json!({"uid": "main", "frame": [0, 0, 1728, 1117]});
    let other = json!({"uid": "other", "frame": [1728, 0, 1920, 1080], "scale": 1});
    otto.call(json!({"cmd": "displays_set", "displays": [main, other], "main": "main"}));
    let state = otto.call(json!({"cmd": "split"}));
    let only = state["state"]["tabs"][0]["id"].as_u64().expect("the workspace's tab");
    let count = state["state"]["tabs"].as_array().map(Vec::len).expect("tabs");
    let state = otto.call(json!({"cmd": "key", "keys": "cmd-shift-o", "as": "user"}));
    assert_eq!(state["out"], json!([{"tab": only, "display": 1}]), "{state}");
    let stand_in = state["windows"][0]["tab"].as_u64().expect("the main window's tab");
    assert_ne!(stand_in, only, "{state}");
    assert_eq!(state["state"]["tabs"].as_array().map(Vec::len), Some(count + 1), "{state}");
    assert!(state["home"].is_null(), "the workspace's empty tab, not Home: {state}");
    otto.drawn();
    assert!(otto.control_opt("home:terminal").is_some(), "its empty state's rows");
    // Fold back in from the main window's row: the stand-in, still empty, goes.
    let [x, y, w, h] = otto.control(&format!("tab-in:{only}"));
    let state = otto.user_click([x + w / 2., y + h / 2.]);
    assert_eq!((&state["out"], &state["windows"][0]["tab"]), (&json!([]), &json!(only)), "{state}");
    assert_eq!(state["state"]["tabs"].as_array().map(Vec::len), Some(count), "{state}");
}

/// At rest the tick sleeps: each frame only for a moment after something happened, then about
/// once a second for the slow looks. It wakes for what happens with no request: a terminal's
/// output, seconds later, is drawn.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn at_rest_the_tick_sleeps_and_wakes_for_output() {
    let otto = Otto::launch("idle-tick");
    otto.call(json!({"cmd": "split"}));
    let state = |o: &Otto| o.call(json!({"cmd": "state"}));
    let ticks = |s: &Value| s["counts"]["ticks"].as_u64().expect("ticks");
    std::thread::sleep(Duration::from_secs(2));
    let before = ticks(&state(&otto));
    std::thread::sleep(Duration::from_secs(4));
    let after = ticks(&state(&otto));
    // A second of frames after the request, then a few slow looks; each frame would be ~240.
    assert!(after - before < 120, "{} ticks in 4 s at rest", after - before);

    otto.call(json!({"cmd": "type", "text": "sleep 3; echo late-$((6*7))\r"}));
    std::thread::sleep(Duration::from_millis(1500));
    let asleep = state(&otto)["frame"]["number"].as_u64().expect("frame");
    std::thread::sleep(Duration::from_secs(4));
    let woken = state(&otto);
    assert!(woken["frame"]["number"].as_u64().expect("frame") > asleep, "the output was not drawn");
    let lines = woken["terminals"]["1"]["lines"].as_array().cloned().unwrap_or_default();
    assert!(lines.iter().any(|l| l.as_str().is_some_and(|l| l.contains("late-42"))), "{lines:?}");
}

/// `<home>/log`: the start, the display the window is on, a change of the displays and the quit,
/// private, in the folder the test named. Counts and sizes only.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn the_log_says_the_start_the_displays_and_the_quit() {
    let home = support::temp(&format!("ottospace-e2e-event-log-{}", std::process::id()));
    let mut otto = Otto::launch_with("event-log", &[("OTTOSPACE_HOME", home.to_str().unwrap())]);
    let file = home.join("log");
    let events = || -> Vec<Value> {
        let text = std::fs::read_to_string(&file).unwrap_or_default();
        text.lines().map(|line| serde_json::from_str(line).expect("a JSON line")).collect()
    };
    let has = |events: &[Value], ev: &str| events.iter().any(|e| e["ev"] == ev);
    otto.call(json!({"cmd": "display_change"}));
    otto.wait_for("the change in the log", |_| Some(events()).filter(|e| has(e, "displays")));
    otto.call(json!({"cmd": "quit"}));
    exits(&mut otto);
    let events = events();
    // Start first, then the change once, the window's display at least once and the quit (a slow
    // machine's stall, or GPUI's warning as the window closes, may come too: not what this is about).
    let names: Vec<&str> = events.iter().filter_map(|e| e["ev"].as_str()).collect();
    assert_eq!(names.first(), Some(&"start"), "{names:?}");
    assert!(names.contains(&"quit"), "{names:?}");
    let count = |ev: &str| names.iter().filter(|name| **name == ev).count();
    assert_eq!(count("displays"), 1, "{names:?}");
    assert!(count("window_display") >= 1, "{names:?}");
    let start = &events[0];
    assert!(start["pid"].is_u64() && start["version"].is_string() && start["displays"]["count"].as_u64() > Some(0));
    let changed = events.iter().find(|e| e["ev"] == "displays").expect("the change");
    let sizes = changed["sizes"].as_array().expect("sizes");
    assert_eq!(changed["count"].as_u64(), Some(sizes.len() as u64));
    // "1728x1117": a size, never a name.
    assert!(sizes.iter().all(|s| s.as_str().is_some_and(|s| s.split('x').all(|n| n.parse::<f64>().is_ok()))));
    assert!(events.iter().all(|e| e["at"].as_str().is_some_and(|at| at.len() == 25)), "{events:?}");
    use std::os::unix::fs::PermissionsExt;
    assert_eq!(std::fs::metadata(&file).unwrap().permissions().mode() & 0o777, 0o600);
}

/// The markdown fixture and its picture, copied into a folder of the test's own: a test may
/// change or remove them. The path as the app resolves it (the temp folder is behind a link).
fn fixture_copy(name: &str) -> PathBuf {
    let dir = support::temp(&format!("ottospace-e2e-{name}-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let from = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/markdown");
    for file in ["fixture.md", "checker.png"] {
        std::fs::copy(from.join(file), dir.join(file)).unwrap();
    }
    std::fs::canonicalize(&dir).unwrap()
}

/// Viewer `pane`'s view in a reply: `state.viewers`.
fn view(reply: &Value, pane: u64) -> Value {
    reply["state"]["viewers"][pane.to_string()].clone()
}

/// The state once viewer `pane` has read its file and been laid out: `lines` read, `most` known.
fn viewer_read(otto: &Otto, pane: u64, lines: u64) -> Value {
    otto.wait_for("the file read and laid out", |o| {
        let state = o.call(json!({"cmd": "state"}));
        let v = view(&state, pane);
        (v["read"] == json!({"status": "shown", "lines": lines}) && v["most"].is_u64()).then_some(state)
    })
}

fn line_count(path: &Path) -> u64 {
    std::fs::read_to_string(path).unwrap().lines().count() as u64
}

#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_file_opens_in_a_viewer_moves_by_counts_reloads_and_edits_beside() {
    let dir = fixture_copy("viewer");
    let file = dir.join("fixture.md");
    let path = file.to_str().unwrap();
    // The stand-in editor: says what it was given, then waits until it is killed.
    let editor = dir.join("edit");
    let script = format!("#!/bin/sh\nprintf '%s\\n' \"$@\" > {}/args\nwhile :; do sleep 0.1; done\n", dir.display());
    std::fs::write(&editor, script).unwrap();
    use std::os::unix::fs::PermissionsExt;
    std::fs::set_permissions(&editor, std::fs::Permissions::from_mode(0o700)).unwrap();
    let env = [("VISUAL", editor.to_str().unwrap()), ("EDITOR", "/usr/bin/false")];
    let otto = Otto::launch_with("viewer", &env);
    otto.call(json!({"cmd": "split"}));

    // A client opens it beside the terminal: the pane says its path, the state its kind and lines.
    let reply = otto.call(json!({"cmd": "open_file", "path": path}));
    assert_eq!(reply["state"]["panes"][1]["kind"], json!({"type": "file", "path": path}));
    assert_eq!((reply["state"]["focused"].as_u64(), view(&reply, 2)["shows"].as_str()), (Some(2), Some("markdown")));
    let lines = line_count(&file);
    let state = viewer_read(&otto, 2, lines);
    assert_eq!(state["viewers"]["2"]["body"], "markdown");
    assert_eq!(state["viewers"]["2"]["shape"]["blocks"]["table"], 2);
    assert_eq!(state["titles"]["2"], "fixture.md");
    // Never the file's text.
    assert!(!state.to_string().contains("pneumonoultramicroscopic"), "the file's text is in the state");

    // A count before a move: the status bar shows it typed; Esc takes it back.
    let reply = otto.call(json!({"cmd": "key", "keys": "1 0"}));
    assert_eq!(view(&reply, 2)["pending"], "10");
    assert_eq!(view(&otto.call(json!({"cmd": "key", "keys": "escape"})), 2)["pending"], Value::Null);
    assert_eq!(view(&otto.call(json!({"cmd": "key", "keys": "1 0 j"})), 2)["top"], 10);
    let most = view(&otto.call(json!({"cmd": "key", "keys": "shift-g"})), 2)["most"].as_u64().unwrap();
    assert!(most > 10, "the fixture is longer than the pane: {most}");
    assert_eq!(view(&otto.call(json!({"cmd": "state"})), 2)["top"], most);
    assert_eq!(view(&otto.call(json!({"cmd": "key", "keys": "g g 5 j"})), 2)["top"], 5);
    // The shell drew it there: its next report says the same line.
    otto.wait_for("the view at line 5", |o| (view(&o.call(json!({"cmd": "state"})), 2)["top"] == 5).then_some(()));
    // Five lines down a long file: both edges fade.
    assert_eq!(fades(&otto.drawn(), "viewer:2"), json!({"top": true, "bottom": true}));

    // Changed on disk: read again, at the same line.
    let mut text = std::fs::read_to_string(&file).unwrap();
    text.push_str("\nOne more line.\n\nAnd another.\n");
    std::fs::write(&file, &text).unwrap();
    let state = viewer_read(&otto, 2, line_count(&file));
    assert_eq!(view(&state, 2)["top"], 5);

    // ⌃G: the user's editor on the file, in a terminal beside the viewer.
    let reply = otto.call(json!({"cmd": "key", "keys": "ctrl-g"}));
    assert_eq!((pane_ids(&reply), reply["state"]["focused"].as_u64()), (vec![1, 2, 3], Some(3)));
    assert_eq!(reply["state"]["panes"][2]["kind"]["type"], "terminal");
    let args = dir.join("args");
    otto.wait_for("the editor", |_| std::fs::read_to_string(&args).ok().filter(|a| *a == format!("{path}\n")));

    // Gone from disk: "File not found", and back when it is.
    std::fs::remove_file(&file).unwrap();
    otto.wait_for("the file missing", |o| {
        (view(&o.call(json!({"cmd": "state"})), 2)["read"]["status"] == "missing").then_some(())
    });
    std::fs::write(&file, "# Back\n").unwrap();
    viewer_read(&otto, 2, 1);

    // A picture; and what is refused: a relative path, a folder, no file.
    let picture = dir.join("checker.png");
    let reply = otto.call(json!({"cmd": "open_file", "path": picture, "beside": 1}));
    let id = pane_ids(&reply).into_iter().max().unwrap();
    assert_eq!(view(&reply, id)["shows"], "image");
    otto.wait_for("the picture", |o| {
        (o.call(json!({"cmd": "state"}))["viewers"][id.to_string()]["body"] == "image").then_some(())
    });
    for bad in [json!("fixture.md"), json!(dir), json!(dir.join("gone.md"))] {
        let reply = otto.raw(&json!({"cmd": "open_file", "path": bad}).to_string());
        assert_eq!(reply["ok"], false, "{bad}: {reply}");
    }
    let reply = otto.raw(&json!({"cmd": "open_file", "path": picture, "beside": 99}).to_string());
    assert_eq!(reply["error"], "no pane 99");

    // The picker's "File…" asks for a file: a test run shows no panel and counts the ask.
    otto.call(json!({"cmd": "picker"}));
    otto.call(json!({"cmd": "picker_query", "query": "file"}));
    let reply = otto.call(json!({"cmd": "picker_choose"}));
    assert_eq!((reply["mode"].as_str(), reply["counts"]["file_prompts"].as_u64()), (Some("normal"), Some(1)));
}

/// Evidence's open: a file at lines comes up scrolled to them, the first drawn marked inside the
/// pane; asked again, the same viewer moves; Esc takes the mark off. Line 0 is refused.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_file_opened_at_lines_shows_them_marked_inside_the_pane() {
    let dir = support::temp(&format!("ottospace-e2e-viewer-at-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let file = std::fs::canonicalize(&dir).unwrap().join("long.rs");
    let text: String = (1..=300).map(|n| format!("fn made_up_{n}() {{}}\n")).collect();
    std::fs::write(&file, text).unwrap();
    let otto = Otto::launch("viewer-at");
    let reply = otto.call(json!({"cmd": "open_file", "path": file, "line": 150, "last": 152}));
    assert_eq!(view(&reply, 1)["marked"], json!({"first": 150, "last": 152}), "{reply}");
    let marked_inside = |o: &Otto, first: f64| {
        let state = o.drawn();
        let row = state["viewers"]["1"]["marked_rect"].clone();
        let pane = rect(&state["bounds"]["1"]);
        let top = view(&state, 1)["top"].as_f64()?;
        let row = row.is_array().then(|| rect(&row))?;
        let inside = row[1] >= pane[1] && row[1] + row[3] <= pane[1] + pane[3];
        // A few lines above it on show.
        (inside && top == first - 4.).then_some(())
    };
    viewer_read(&otto, 1, 300);
    otto.wait_for("line 150 marked in the pane", |o| marked_inside(o, 150.));
    // Again at other lines: the same viewer moves there.
    let reply = otto.call(json!({"cmd": "open_file", "path": file, "line": 40}));
    assert_eq!((pane_ids(&reply), view(&reply, 1)["marked"].clone()), (vec![1], json!({"first": 40, "last": 40})));
    otto.wait_for("line 40 marked in the pane", |o| marked_inside(o, 40.));
    let reply = otto.raw(&json!({"cmd": "open_file", "path": file, "line": 0}).to_string());
    assert_eq!(reply["error"], "open_file: lines count from 1");
    let reply = otto.call(json!({"cmd": "key", "keys": "escape"}));
    assert_eq!(view(&reply, 1)["marked"], Value::Null);
}

/// A code file is coloured by its grammar; one with none, or past the parse's 2 MB, by the lexer:
/// its lines show all the same.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_code_file_is_coloured_by_its_grammar_or_the_lexer_when_it_has_none_or_is_too_large() {
    let dir = support::temp(&format!("ottospace-e2e-viewer-syntax-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let dir = std::fs::canonicalize(&dir).unwrap();
    let small = "fn made_up() {}\n".repeat(40);
    let large = "fn made_up() {}\n".repeat(2 * 1024 * 1024 / 16 + 1);
    let mut cases = vec![
        ("small.rs", small.clone(), json!("rust")),
        ("small.scss", small, Value::Null),
        ("large.rs", large, Value::Null),
    ];
    // Each language's made-up file, by its extension or its whole name.
    let code = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/code");
    for (name, syntax) in [
        ("seeds.go", "go"),
        ("seeds.c", "c"),
        ("seeds.cpp", "cpp"),
        ("Seeds.java", "java"),
        ("Seeds.cs", "csharp"),
        ("seeds.rb", "ruby"),
        ("seeds.html", "html"),
        ("seeds.css", "css"),
        ("seeds.yml", "yaml"),
        ("seeds.sql", "sql"),
        ("seeds.php", "php"),
        ("seeds.lua", "lua"),
        ("Makefile", "make"),
        ("seeds.xml", "xml"),
        ("seeds.md", "markdown"),
    ] {
        cases.push((name, std::fs::read_to_string(code.join(name)).unwrap(), json!(syntax)));
    }
    let otto = Otto::launch("viewer-syntax");
    for (name, text, syntax) in cases {
        let file = dir.join(name);
        std::fs::write(&file, text).unwrap();
        // Each in a viewer of its own: the newest pane. Markdown at a line: its source.
        let line = name.ends_with(".md").then_some(1);
        let open = json!({"cmd": "open_file", "path": file, "line": line});
        let id = pane_ids(&otto.call(open)).into_iter().max().unwrap();
        let drawn = viewer_read(&otto, id, line_count(&file))["viewers"][id.to_string()].clone();
        assert_eq!((&drawn["body"], &drawn["syntax"]), (&json!("lines"), &syntax), "{name}");
    }
}

/// The fixture's structure as drawn: callouts, footnotes at the foot, task boxes; a code line
/// and a table wider than the pane scroll across, their right edge fading as the cue.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn the_markdown_viewer_draws_callouts_footnotes_tasks_and_wide_blocks_that_scroll_across() {
    let dir = fixture_copy("viewer-structure");
    let file = dir.join("fixture.md");
    let otto = Otto::launch("viewer-structure");
    // In the empty tab's only pane: pane 1.
    otto.call(json!({"cmd": "open_file", "path": file}));
    let state = viewer_read(&otto, 1, line_count(&file));
    let blocks = &state["viewers"]["1"]["shape"]["blocks"];
    let counts = ["quote", "callout", "footnotes", "task", "image"].map(|kind| blocks[kind].as_u64());
    assert_eq!(counts, [Some(2), Some(3), Some(1), Some(5), Some(1)], "{blocks}");
    // Seven web links: five written as links, and two bare (`https://example.com/bare`, the Slack one).
    assert_eq!(state["viewers"]["1"]["shape"]["links"]["web"], 7, "{state}");
    let across = |prefix: &str| {
        let overflow = otto.drawn()["overflow"].clone();
        let areas = overflow.as_object().cloned().unwrap_or_default();
        areas.into_iter().filter(|(id, _)| id.starts_with(prefix)).map(|(_, edges)| edges).collect::<Vec<_>>()
    };
    let code = across("chat-code:viewer:1.");
    assert!(code.contains(&json!({"left": false, "right": true})), "a long line fades at the right: {code:?}");
    assert!(code.iter().filter(|edges| edges["right"] == true).count() == 1, "only the long one: {code:?}");
    let tables = across("chat-table:viewer:1.");
    assert_eq!(tables.len(), 2, "{tables:?}");
    assert!(tables.contains(&json!({"left": false, "right": true})), "the wide table: {tables:?}");
}

#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_viewer_comes_back_after_a_restart_at_its_line() {
    let dir = fixture_copy("viewer-restart");
    let home = support::temp(&format!("ottospace-e2e-home-viewer-{}", std::process::id()));
    std::fs::create_dir_all(&home).unwrap();
    let file = dir.join("fixture.md");
    let path = file.to_str().unwrap();
    let env = [("OTTOSPACE_HOME", home.to_str().unwrap())];
    let mut otto = Otto::launch_with("viewer-restart-1", &env);
    otto.call(json!({"cmd": "open_file", "path": path}));
    viewer_read(&otto, 1, line_count(&file));
    otto.call(json!({"cmd": "key", "keys": "2 0 j"}));
    otto.wait_for("the view at line 20", |o| (view(&o.call(json!({"cmd": "state"})), 1)["top"] == 20).then_some(()));
    otto.call(json!({"cmd": "quit"}));
    exits(&mut otto);
    let text = std::fs::read_to_string(home.join("layout.json")).unwrap();
    assert!(text.contains("\"type\": \"file\"") && text.contains("\"top\": 20"), "{text}");
    assert!(!text.contains("pneumonoultramicroscopic"), "the file's text is not kept");

    let otto = Otto::launch_with("viewer-restart-2", &env);
    let state = viewer_read(&otto, 1, line_count(&file));
    assert_eq!(state["state"]["panes"][0]["kind"], json!({"type": "file", "path": path}));
    otto.wait_for("the view back at line 20", |o| {
        (view(&o.call(json!({"cmd": "state"})), 1)["top"] == 20).then_some(())
    });
}

#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_cmd_click_on_a_path_in_a_terminal_opens_the_viewer_beside_and_reuses_it() {
    let dir = fixture_copy("viewer-click");
    std::fs::write(dir.join("notes.txt"), "one\ntwo\n").unwrap();
    let otto = Otto::launch("viewer-click");
    otto.call(json!({"cmd": "split"}));
    let typed = format!("cd '{}' && printf 'fixture.md\\nnotes.txt:2\\n'\r", dir.display());
    otto.call(json!({"cmd": "type", "pane": 1, "text": typed}));
    otto.call(json!({"cmd": "wait", "pane": 1, "pattern": "^notes.txt:2$"}));
    let state = otto.drawn();
    let lines: Vec<String> =
        state["terminals"]["1"]["lines"].as_array().unwrap().iter().map(|l| l.as_str().unwrap().to_string()).collect();
    let bounds = rect(&state["bounds"]["1"]);
    let cell = (state["cell"][0].as_f64().unwrap(), state["cell"][1].as_f64().unwrap());
    let on = |text: &str| {
        let row =
            lines.iter().position(|line| line == text).unwrap_or_else(|| panic!("{text} not on screen: {lines:?}"));
        [bounds[0] + cell.0 * 2.5, bounds[1] + cell.1 * (row as f64 + 0.5)]
    };
    let cmd_click = |p: [f64; 2]| {
        otto.call(json!({"cmd": "mouse", "action": "down", "x": p[0], "y": p[1], "modifiers": ["cmd"]}));
        otto.call(json!({"cmd": "mouse", "action": "up", "x": p[0], "y": p[1], "modifiers": ["cmd"]}))
    };
    let fixture = dir.join("fixture.md");
    cmd_click(on("fixture.md"));
    let reply = otto.wait_for("the viewer", |o| {
        let state = o.call(json!({"cmd": "state"}));
        (pane_ids(&state) == [1, 2]).then_some(state)
    });
    assert_eq!(reply["state"]["panes"][1]["kind"], json!({"type": "file", "path": fixture}));
    assert_eq!((reply["state"]["focused"].as_u64(), view(&reply, 2)["opener"].as_u64()), (Some(1), Some(1)));
    // The next one goes to the same viewer; the line number is no part of the path.
    cmd_click(on("notes.txt:2"));
    let reply = otto.wait_for("the viewer reused", |o| {
        let state = o.call(json!({"cmd": "state"}));
        (state["state"]["panes"][1]["kind"]["path"] == json!(dir.join("notes.txt"))).then_some(state)
    });
    assert_eq!((pane_ids(&reply), view(&reply, 2)["shows"].as_str()), (vec![1, 2], Some("text")));
}

/// A URL a terminal printed opens on the user's ⌘-click alone: a plain click selects, and a
/// client's ⌘-click opens nothing. A test run opens no browser; it counts.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_cmd_click_on_a_terminal_link_opens_it_for_the_user_alone() {
    let otto = Otto::launch("term-links");
    otto.call(json!({"cmd": "split"}));
    otto.call(json!({"cmd": "type", "pane": 1, "text": "printf 'see https://example.com/docs now\\n'\r"}));
    otto.call(json!({"cmd": "wait", "pane": 1, "pattern": "^see https://example.com/docs now$"}));
    let state = otto.drawn();
    let lines = state["terminals"]["1"]["lines"].as_array().unwrap();
    let row = lines.iter().position(|l| l.as_str().is_some_and(|l| l.starts_with("see "))).unwrap();
    let bounds = rect(&state["bounds"]["1"]);
    let cell = (state["cell"][0].as_f64().unwrap(), state["cell"][1].as_f64().unwrap());
    let on = [bounds[0] + cell.0 * 10.5, bounds[1] + cell.1 * (row as f64 + 0.5)];
    let click = |modifiers: &[&str], user: bool| {
        let event = |action: &str| {
            let mut event = json!({"cmd": "mouse", "action": action, "x": on[0], "y": on[1], "modifiers": modifiers});
            if user {
                event["as"] = json!("user");
            }
            event
        };
        otto.call(event("down"));
        otto.call(event("up"))["counts"]["link_opens"].as_u64()
    };
    assert_eq!(click(&[], true), Some(0), "a plain click");
    assert_eq!(click(&["cmd"], false), Some(0), "a client's ⌘-click");
    assert_eq!(click(&["cmd"], true), Some(1), "the user's ⌘-click");
}

/// A new window of a hosted app never splits its pane by itself: it floats, and the app pane's
/// header offers it, saying why it is in no pane. Only the user's click puts it in a pane; a
/// client's is refused. Dismissed, or closed, the offer goes. A dialog is offered too. Each
/// placement is one line in the log, never with the title, nor is the title in the state.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_new_window_floats_with_an_offer_and_only_the_users_click_puts_it_in_a_pane() {
    let home = user_folder("pop-up", r#"{"repos": [], "restore_layout": false}"#);
    let otto = Otto::launch_with("pop-up", &[("OTTOSPACE_HOME", home.to_str().unwrap())]);
    let reply = otto.call(json!({"cmd": "app_fixture", "name": "Meetings", "user": true}));
    let pane = reply["state"]["focused"].as_u64().unwrap();
    let opened = |title: &str, subrole: &str| {
        let line =
            json!({"cmd": "window_fixture", "pane": pane, "title": title, "subrole": subrole, "size": [1200, 800]});
        otto.call(line)
    };
    let offers = |reply: &Value| reply["state"]["offers"].clone();
    let panes = |reply: &Value| reply["state"]["panes"].as_array().map_or(0, Vec::len);
    // A big standard window: offered, no split, its title nowhere in the reply.
    let reply = opened("Meeting SECRET room", "AXStandardWindow");
    assert_eq!(offers(&reply), json!([{"pane": pane, "window": 800001}]), "{reply}");
    assert_eq!(panes(&reply), 1, "no split by itself");
    assert!(!reply.to_string().contains("SECRET"), "{reply}");
    // A dialog is offered too: the user may want it in a pane. Dismissed, it floats on.
    assert_eq!(offers(&opened("Settings", "AXDialog")).as_array().map(Vec::len), Some(2));
    // Two offers group in one chip: its list holds each.
    otto.user_click(at(otto.control(&format!("offer-list:{pane}")), 0.5, 0.5));
    otto.user_click(at(otto.control("offer-dismiss:800002"), 0.5, 0.5));
    // A client's click on the chip is refused, and says why.
    let put = otto.control("offer:800001");
    let reply = otto.click(at(put, 0.5, 0.5), 1);
    assert_eq!(offers(&reply).as_array().map(Vec::len), Some(1), "{reply}");
    assert!(reply["notice"].as_str().is_some_and(|n| n.contains("only they put it in a pane")), "{reply}");
    // The user's puts it in a pane beside its app's; the offer goes.
    let reply = otto.user_click(at(put, 0.5, 0.5));
    let state = otto.call(json!({"cmd": "state"}));
    assert_eq!((panes(&state), offers(&state)), (2, json!([])), "{reply}");
    let held = state["state"]["panes"].as_array().unwrap().iter().any(|p| p["kind"]["window"] == 800001);
    assert!(held, "{state}");
    // Dismissed: it stays floating, no pane.
    opened("Second", "AXStandardWindow");
    otto.user_click(at(otto.control("offer-dismiss:800003"), 0.5, 0.5));
    let state = otto.call(json!({"cmd": "state"}));
    assert_eq!((panes(&state), offers(&state)), (2, json!([])));
    // Closed: the offer goes.
    opened("Third", "AXStandardWindow");
    let reply = otto.call(json!({"cmd": "window_fixture_close", "window": 800004}));
    assert_eq!(offers(&reply), json!([]));
    // One line a placement: where it went and why; never a title.
    let log = std::fs::read_to_string(home.join("log")).unwrap();
    let placed: Vec<Value> =
        log.lines().map(|line| serde_json::from_str::<Value>(line).unwrap()).filter(|e| e["ev"] == "place").collect();
    let said: Vec<(Value, Value)> = placed.iter().map(|e| (e["place"].clone(), e["why"].clone())).collect();
    let offer = (json!("offer"), json!("no_slot"));
    assert_eq!(said, [offer.clone(), (json!("offer"), json!("dialog")), offer.clone(), offer], "{log}");
    assert_eq!((&placed[0]["subrole"], &placed[0]["size"]), (&json!("AXStandardWindow"), &json!([1200.0, 800.0])));
    assert!(!log.contains("SECRET") && !log.contains("Second"), "{log}");
}

/// The owner's call: an offer splits right or down, as the user picks. Several offers of one pane
/// group in one chip, `opened 2 windows ▾`; only the user's ▾ opens their list, each window with
/// the same three choices. No title in the reply.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn an_offer_splits_right_or_down_and_several_group_in_one_chip() {
    let otto = Otto::launch("offer-choices");
    let reply = otto.call(json!({"cmd": "app_fixture", "name": "Meetings", "user": true}));
    let pane = reply["state"]["focused"].as_u64().unwrap();
    let opened = |title: &str| {
        let line = json!({"cmd": "window_fixture", "pane": pane, "title": title, "subrole": "AXStandardWindow",
            "size": [900, 600]});
        otto.call(line)
    };
    opened("SECRET chat");
    assert!(otto.control_opt("offer:800001").is_some() && otto.control_opt("offer-down:800001").is_some());
    let reply = opened("SECRET notes");
    assert_eq!(reply["state"]["offers"].as_array().map(Vec::len), Some(2), "{reply}");
    // Grouped: one ▾, no single offer's choices in the header.
    let list = otto.control(&format!("offer-list:{pane}"));
    assert_eq!(otto.control_opt("offer-down:800001"), None);
    assert_eq!(otto.click(at(list, 0.5, 0.5), 1)["state"]["offer_list"], Value::Null, "a client's ▾ is refused");
    let reply = otto.user_click(at(list, 0.5, 0.5));
    assert_eq!(reply["state"]["offer_list"], json!(pane), "{reply}");
    assert!(!reply.to_string().contains("SECRET"), "{reply}");
    // Each window in the list, with its three choices. ⊟ splits the first in below its app's pane.
    for id in ["offer:800001", "offer-down:800001", "offer-dismiss:800001", "offer:800002"] {
        assert!(otto.control_opt(id).is_some(), "{id}");
    }
    otto.user_click(at(otto.control("offer-down:800001"), 0.5, 0.5));
    let state = otto.call(json!({"cmd": "state"}));
    let panes: Vec<u64> = state["state"]["panes"].as_array().unwrap().iter().filter_map(|p| p["id"].as_u64()).collect();
    let new = *panes.iter().find(|id| **id != pane).expect("a pane for the window");
    let (app, below) = (rect(&state["bounds"][pane.to_string()]), rect(&state["bounds"][new.to_string()]));
    assert!(below[1] > app[1] + app[3] - 1.0 && (below[0] - app[0]).abs() < 1.0, "below: {app:?} {below:?}");
    // One left: no list, its own choices in the chip again.
    assert_eq!(state["state"]["offer_list"], Value::Null, "{state}");
    assert!(otto.control_opt("offer-down:800002").is_some());
}

/// In a narrow pane the offer chip cuts its line short; the pointer on its words shows the whole
/// line, title and reason, in a tooltip drawn inside the window. The tooltip takes no click meant
/// for the chip, and the title is never in the state.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn hovering_an_offer_chips_words_shows_its_whole_line_and_the_state_holds_no_title() {
    let otto = Otto::launch_with("offer-tip", &[("OTTOSPACE_E2E_WINDOW", "1024x674")]);
    otto.call(json!({"cmd": "split", "axis": "right"}));
    let reply = otto.call(json!({"cmd": "app_fixture", "name": "Meetings", "user": true}));
    let pane = reply["state"]["focused"].as_u64().unwrap();
    let title = "SECRET quarterly planning review";
    otto.call(json!({"cmd": "window_fixture", "pane": pane, "title": title, "size": [1200, 800]}));
    let state = |o: &Otto| o.call(json!({"cmd": "state"}));
    let words = format!("words:{pane}");
    let drawn = |o: &Otto| Some(state(o)).filter(|s| !s["offer_rects"][&words].is_null());
    let reply = otto.wait_for("the chip's words", drawn);
    assert_eq!(reply["offer_rects"]["tip"], Value::Null, "no tooltip before a hover");
    let line = rect(&reply["offer_rects"][&words]);
    assert!(line[2] > 40., "words to point at: {line:?}");
    otto.mouse("move", at(line, 0.5, 0.5));
    let shown = |o: &Otto| Some(state(o)).filter(|s| !s["offer_rects"]["tip"].is_null());
    let reply = otto.wait_for("the tooltip", shown);
    let (tip, window) = (rect(&reply["offer_rects"]["tip"]), rect(&reply["window"]));
    let inside = tip[0] >= 0. && tip[1] >= 0. && tip[0] + tip[2] <= window[2] && tip[1] + tip[3] <= window[3];
    assert!(inside && tip[2] > line[2], "a whole line, inside the window: {tip:?} {line:?} {window:?}");
    assert!(!reply.to_string().contains("SECRET"), "{reply}");
    // The chip's ⊟ still takes the user's click.
    let reply = otto.user_click(at(otto.control("offer-down:800001"), 0.5, 0.5));
    assert_eq!(reply["state"]["offers"], json!([]), "{reply}");
    let gone = |o: &Otto| Some(o.drawn()).filter(|s| s["offer_rects"].as_object().is_some_and(|r| r.is_empty()));
    otto.wait_for("no chip, no tooltip", gone);
}

/// Zoom's meeting opens windows of one title: in the offer list each of them gets a detail and a
/// picture (a test run's fixture: a box of its shape), a window of its own title none. Neither
/// title nor detail is in the state.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn offered_windows_of_one_title_are_told_apart_in_the_offer_list() {
    let otto = Otto::launch("offer-same-title");
    let reply = otto.call(json!({"cmd": "app_fixture", "name": "Meetings", "user": true}));
    let pane = reply["state"]["focused"].as_u64().unwrap();
    for (title, size) in [("SECRET meeting", [1280, 800]), ("SECRET meeting", [400, 600]), ("Chat", [400, 600])] {
        otto.call(json!({"cmd": "window_fixture", "pane": pane, "title": title, "size": size}));
    }
    otto.user_click(at(otto.control(&format!("offer-list:{pane}")), 0.5, 0.5));
    let drawn = |o: &Otto| Some(o.drawn()).filter(|s| !s["offer_rects"]["thumb:800002"].is_null());
    let reply = otto.wait_for("the list's pictures", drawn);
    let (big, tall) = (rect(&reply["offer_rects"]["thumb:800001"]), rect(&reply["offer_rects"]["thumb:800002"]));
    assert!(big[2] > tall[2] + 10., "each of its window's shape: {big:?} {tall:?}");
    assert_eq!(reply["offer_rects"]["thumb:800003"], Value::Null, "a title of its own: none");
    let said = reply.to_string();
    assert!(!said.contains("SECRET") && !said.contains("1280×800") && !said.contains("400×600"), "{reply}");
}

/// The user's ⋯ on pane `pane`, then its menu's `item` (`slot_keep`, `slot_edit`, `slot_give_back`, `slot_clear`).
fn slot_menu(otto: &Otto, pane: u64, item: &str) -> Value {
    let reply = otto.user_click(at(otto.control(&format!("slot-dots:{pane}")), 0.5, 0.5));
    let items = reply["row_menu"]["items"].as_array().cloned().unwrap_or_default();
    let index = items.iter().position(|i| i["item"] == item).unwrap_or_else(|| panic!("no {item}: {reply}"));
    otto.user_click(at(otto.control(&format!("row-menu:{index}")), 0.5, 0.5))
}

/// Slots on screen (`slots` flag): ⋯ on an app pane's header opens its menu, whose Keep opens the dialog, by the pane's
/// window's id; Keep makes the pane a filled slot, marked `slot`. ⋯'s Give back the window
/// leaves it waiting, saying what for; a window the slot selects is offered there, not in a
/// chip, and only the user's Bring it here fills it. No title or id the looks carried is in the
/// state while it waits. A test run hosts no window: the looks are fixtures (`slot_windows`).
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_slot_is_made_from_the_dialog_waits_says_what_for_and_only_the_user_fills_it() {
    let otto = Otto::launch_with("slot-dialog", &[("OTTOSPACE_FEATURES", "slots")]);
    let reply = otto.call(json!({"cmd": "app_fixture", "name": "Meetings", "user": true}));
    let pane = reply["state"]["focused"].as_u64().unwrap();
    let window = reply["state"]["panes"][0]["kind"]["window"].as_u64().unwrap();
    let seen = |window: u64, title: &str, id: Option<&str>| {
        json!({"pid": 0, "window": window, "title": title, "identifier": id, "subrole": "AXStandardWindow",
            "frame": {"x": 0, "y": 0, "w": 900, "h": 700}})
    };
    let look = |windows: Vec<Value>| {
        let displays = [json!({"x": 0, "y": 0, "w": 1920, "h": 1080})];
        json!({"cmd": "slot_windows", "look": {"name": "Meetings", "running": true, "windows": windows, "displays": displays}})
    };
    otto.call(look(vec![seen(window, "SECRET sync", Some("zm.meeting.window.main"))]));
    // A client's ⋯ is refused; the user's opens its menu, whose Keep opens the dialog, by the window's id.
    let dots = otto.control(&format!("slot-dots:{pane}"));
    let reply = otto.click(at(dots, 0.5, 0.5), 1);
    assert_eq!((&reply["row_menu"], &reply["state"]["slot_dialog"]), (&Value::Null, &Value::Null), "{reply}");
    let reply = otto.user_click(at(dots, 0.5, 0.5));
    let items = &reply["row_menu"]["items"];
    assert_eq!((&items[0]["item"], &items[0]["label"]), (&json!("slot_keep"), &json!("Create slot…")), "{reply}");
    let reply = otto.user_click(at(otto.control("row-menu:0"), 0.5, 0.5));
    let dialog = &reply["state"]["slot_dialog"];
    assert_eq!((&dialog["by"], &dialog["editing"]), (&json!("id"), &json!(false)), "{reply}");
    assert!(!reply.to_string().contains("SECRET") && !reply.to_string().contains("zm.meeting"), "{reply}");
    let reply = otto.user_click(at(otto.control("slot-dialog:keep"), 0.5, 0.5));
    let slot = |reply: &Value| reply["state"]["slots"][pane.to_string()].clone();
    assert_eq!((slot(&reply)["status"].clone(), reply["state"]["slot_dialog"].clone()), (json!("filled"), Value::Null));
    // Give back the window, in ⋯'s menu: the slot waits, passing over that window.
    let reply = slot_menu(&otto, pane, "slot_give_back");
    assert_eq!(reply["state"]["panes"][0]["kind"]["type"], "slot", "{reply}");
    // Its window comes back as another one: offered in the slot, not in a chip.
    let reply = otto.call(look(vec![seen(700_001, "SECRET sync", Some("zm.meeting.window.main"))]));
    assert_eq!((slot(&reply)["status"].clone(), reply["state"]["offers"].clone()), (json!("offered"), json!([])));
    assert!(!reply.to_string().contains("SECRET") && !reply.to_string().contains("zm.meeting"), "{reply}");
    // A client's Bring it here, click or ↵, is refused; the user's ↵ fills it.
    let accept = otto.control(&format!("slot-accept:{pane}"));
    assert_eq!(slot(&otto.click(at(accept, 0.5, 0.5), 1))["status"], "offered");
    assert_eq!(slot(&otto.call(json!({"cmd": "key", "keys": "enter"})))["status"], "offered");
    let reply = otto.call(json!({"cmd": "key", "keys": "enter", "as": "user"}));
    let state = otto.call(json!({"cmd": "state"}));
    assert_eq!(slot(&state)["status"], "filled", "{reply}");
    assert_eq!(state["state"]["panes"][0]["kind"]["window"], 700_001);
}

/// The slot dialog (board H4): its rule in one line over a form. A window with no id: any window
/// of the app, the largest. The user's Title, starts with, and the words cut down to "SECRET
/// weekly" make a slot that takes both weekly windows and not Home; a client's click or key changes
/// nothing. Edited again it is as kept; × closes it. No title, id or typed word is in the state.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn the_slot_dialog_tightens_its_rule_by_title_and_keep_saves_it() {
    let otto = Otto::launch_with("slot-form", &[("OTTOSPACE_FEATURES", "slots")]);
    let reply = otto.call(json!({"cmd": "app_fixture", "name": "Meetings", "user": true}));
    let pane = reply["state"]["focused"].as_u64().unwrap();
    let window = reply["state"]["panes"][0]["kind"]["window"].as_u64().unwrap();
    let seen = |window: u64, title: &str, w: u32| {
        json!({"pid": 0, "window": window, "title": title, "subrole": "AXStandardWindow",
            "frame": {"x": 0, "y": 0, "w": w, "h": 500}})
    };
    let look = |windows: Vec<Value>| {
        let displays = [json!({"x": 0, "y": 0, "w": 1920, "h": 1080})];
        json!({"cmd": "slot_windows", "look": {"name": "Meetings", "running": true, "windows": windows, "displays": displays}})
    };
    otto.call(look(vec![
        seen(window, "SECRET weekly sync", 900),
        seen(800_101, "SECRET weekly planning", 600),
        seen(800_102, "Home", 400),
    ]));
    let reply = slot_menu(&otto, pane, "slot_keep");
    let dialog = &reply["state"]["slot_dialog"];
    assert_eq!((&dialog["has_id"], &dialog["by"], &dialog["pick"]), (&json!(false), &json!("any"), &json!("largest")));
    // A client's click on Title is refused; the user's chooses it, and the words have the keys.
    let title = otto.control("slot-dialog:by-title");
    assert_eq!(otto.click(at(title, 0.5, 0.5), 1)["state"]["slot_dialog"]["by"], "any");
    assert_eq!(otto.user_click(at(title, 0.5, 0.5))["state"]["slot_dialog"]["by"], "title");
    let reply = otto.user_click(at(otto.control("slot-dialog:starts-with"), 0.5, 0.5));
    assert_eq!(reply["state"]["slot_dialog"]["test"], "starts_with");
    // The words are the window's title: the user cuts " sync"; a client's typing does not reach them.
    otto.call(json!({"cmd": "key", "keys": "backspace backspace backspace backspace backspace", "as": "user"}));
    let reply = otto.call(json!({"cmd": "key", "keys": "x"}));
    assert!(!reply.to_string().contains("SECRET"), "{reply}");
    let reply = otto.user_click(at(otto.control("slot-dialog:keep"), 0.5, 0.5));
    let slot = |reply: &Value| reply["state"]["slots"][pane.to_string()].clone();
    assert_eq!((slot(&reply)["status"].clone(), reply["state"]["slot_dialog"].clone()), (json!("filled"), Value::Null));
    // Waiting, it takes the weekly windows only.
    slot_menu(&otto, pane, "slot_give_back");
    let reply = otto.call(look(vec![
        seen(700_001, "SECRET weekly sync", 900),
        seen(700_002, "SECRET weekly planning", 600),
        seen(700_003, "Home", 400),
    ]));
    assert_eq!(
        (slot(&reply)["status"].clone(), slot(&reply)["matches"].clone()),
        (json!("offered"), json!(2)),
        "{reply}"
    );
    // Edit slot…: as kept. × closes it, as Esc does.
    let reply = slot_menu(&otto, pane, "slot_edit");
    let dialog = &reply["state"]["slot_dialog"];
    assert_eq!(
        (&dialog["by"], &dialog["test"], &dialog["editing"]),
        (&json!("title"), &json!("starts_with"), &json!(true))
    );
    assert!(!reply.to_string().contains("SECRET"), "{reply}");
    let reply = otto.user_click(at(otto.control("slot-dialog:cancel"), 0.5, 0.5));
    assert_eq!(reply["state"]["slot_dialog"], Value::Null, "{reply}");
}

/// A window the user put in a pane (no Keep) closing leaves the pane, a slot waiting for that
/// kind of window and saying so, with a Close of its own; a client's pane closes with its window.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_users_app_pane_whose_window_closes_stays_a_waiting_slot() {
    let otto = Otto::launch_with("slot-kept", &[("OTTOSPACE_FEATURES", "slots")]);
    let theirs = otto.call(json!({"cmd": "app_fixture", "name": "Meetings", "user": false}));
    let theirs = theirs["state"]["panes"][0]["kind"]["window"].as_u64().unwrap();
    let reply = otto.call(json!({"cmd": "app_fixture", "name": "Meetings", "user": true}));
    let pane = reply["state"]["focused"].as_u64().unwrap();
    let mine = reply["state"]["panes"][1]["kind"]["window"].as_u64().unwrap();
    let seen = json!({"pid": 0, "window": mine, "title": "SECRET standup", "identifier": "zm.meeting.window.main",
        "subrole": "AXStandardWindow", "frame": {"x": 0, "y": 0, "w": 900, "h": 700}});
    let displays = [json!({"x": 0, "y": 0, "w": 1920, "h": 1080})];
    otto.call(json!({"cmd": "slot_windows", "look": {"name": "Meetings", "running": true, "windows": [seen], "displays": displays}}));
    let reply = otto.call(json!({"cmd": "window_fixture_close", "window": theirs}));
    assert_eq!(reply["state"]["panes"].as_array().map(Vec::len), Some(1), "a client's closes: {reply}");
    let reply = otto.call(json!({"cmd": "window_fixture_close", "window": mine}));
    let state = &reply["state"];
    assert_eq!(
        (&state["panes"][0]["id"], &state["panes"][0]["kind"]["type"]),
        (&json!(pane), &json!("slot")),
        "{reply}"
    );
    assert_eq!(state["slots"][pane.to_string()]["status"], "away");
    assert!(!reply.to_string().contains("SECRET") && !reply.to_string().contains("zm.meeting"), "{reply}");
    // Its ×: a client's click is refused, the user's closes it.
    let close = otto.control(&format!("close:{pane}"));
    assert_eq!(otto.click(at(close, 0.5, 0.5), 1)["state"]["panes"].as_array().map(Vec::len), Some(1));
    let reply = otto.user_click(at(close, 0.5, 0.5));
    let left = reply["state"]["panes"].as_array().unwrap().iter().any(|p| p["id"] == json!(pane));
    assert!(!left && reply["state"]["slots"][pane.to_string()].is_null(), "{reply}");
}

/// The owner's call: three slots that each select any Meetings window take three new windows one
/// by one, in reading order: one window a slot, never two slots one window. Manual offers; the
/// user's Bring it here fills each.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn three_app_only_slots_take_three_windows_one_by_one() {
    let otto = Otto::launch_with("slot-three", &[("OTTOSPACE_FEATURES", "slots")]);
    let mut panes = Vec::new();
    for _ in 0..3 {
        let reply = otto.call(json!({"cmd": "app_fixture", "name": "Meetings", "user": true}));
        let pane = reply["state"]["focused"].as_u64().unwrap();
        otto.call(json!({"cmd": "slot_make", "pane": pane, "slot": {"select": {}}}));
        slot_menu(&otto, pane, "slot_give_back");
        panes.push(pane);
    }
    let windows: Vec<Value> = (1..=3)
        .map(|n| {
            json!({"pid": 0, "window": 710_000 + n, "title": format!("Meeting {n}"), "subrole": "AXStandardWindow",
                "frame": {"x": 0, "y": 0, "w": 900, "h": 700}})
        })
        .collect();
    let displays = [json!({"x": 0, "y": 0, "w": 1920, "h": 1080})];
    let reply = otto.call(
        json!({"cmd": "slot_windows", "look": {"name": "Meetings", "running": true, "windows": windows, "displays": displays}}),
    );
    let status: Vec<Value> = panes.iter().map(|p| reply["state"]["slots"][p.to_string()]["status"].clone()).collect();
    assert_eq!(status, [json!("offered"), json!("offered"), json!("offered")], "{reply}");
    for pane in &panes {
        otto.user_click(at(otto.control(&format!("slot-accept:{pane}")), 0.5, 0.5));
    }
    let state = otto.call(json!({"cmd": "state"}));
    let held: Vec<(u64, u64)> = state["state"]["panes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| (p["id"].as_u64().unwrap(), p["kind"]["window"].as_u64().unwrap_or(0)))
        .collect();
    let want: Vec<(u64, u64)> = panes.iter().zip(710_001..).map(|(p, w)| (*p, w)).collect();
    assert_eq!(held, want, "in reading order, one window each: {state}");
}

/// A real git checkout standing for ottospace's repository, one commit on `main`, and a home
/// whose settings name it (`developer.ottospace_repo`). Both under `support::temp`.
fn bug_setup(name: &str) -> (PathBuf, PathBuf) {
    let root = support::temp(&format!("ottospace-e2e-bug-{name}-{}", std::process::id()));
    let repo = root.join("ottospace");
    std::fs::create_dir_all(&repo).unwrap();
    git(&repo, &["init", "-q", "-b", "main"]);
    git(&repo, &["-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "--allow-empty", "-m", "one"]);
    let repo = repo.canonicalize().unwrap();
    let settings = json!({"developer": {"ottospace_repo": repo}, "restore_layout": false}).to_string();
    (repo, user_folder(&format!("bug-{name}"), &settings))
}

/// The report once it is drawn: the picture is taken off the main thread first.
fn bug_report(otto: &Otto) -> Value {
    otto.wait_for("the bug report", |o| {
        let s = o.call(json!({"cmd": "state"}));
        (!s["bug"]["report"].is_null()).then_some(s)
    })
}

#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn bug_button_shows_only_for_a_checkout_and_only_the_user_starts_a_report() {
    // No setting: no button.
    let plain = user_folder("bug-none", r#"{"restore_layout": false}"#);
    let otto = Otto::launch_with("bug-none", &[("OTTOSPACE_HOME", plain.to_str().unwrap())]);
    let state = otto.drawn();
    assert_eq!(state["bug"]["icon"], false, "{}", state["bug"]);
    assert!(!otto.controls().iter().any(|(id, _)| id == "top:bug"), "a bug button with no setting");
    drop(otto);
    let (_repo, home) = bug_setup("button");
    let otto = Otto::launch_with("bug-button", &[("OTTOSPACE_HOME", home.to_str().unwrap())]);
    assert_eq!(otto.drawn()["bug"]["icon"], true);
    let button = otto.control("top:bug");
    // A client's click and key start nothing.
    otto.click(at(button, 0.5, 0.5), 1);
    otto.call(json!({"cmd": "key", "keys": "cmd-ctrl-b"}));
    std::thread::sleep(Duration::from_millis(400));
    assert!(otto.call(json!({"cmd": "state"}))["bug"]["report"].is_null(), "a client started a report");
    // The user's key does.
    otto.user_key("cmd-ctrl-b");
    let state = bug_report(&otto);
    assert_eq!((&state["mode"], &state["bug"]["report"]["marks"]), (&json!("annotate"), &json!([])));
    // Esc cancels: nothing is kept.
    otto.user_key("escape");
    assert!(otto.call(json!({"cmd": "state"}))["bug"]["report"].is_null());
}

#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn bug_the_users_drag_marks_a_box_with_a_comment_and_a_client_types_none() {
    let (_repo, home) = bug_setup("mark");
    let otto = Otto::launch_with("bug-mark", &[("OTTOSPACE_HOME", home.to_str().unwrap())]);
    otto.call(json!({"cmd": "split"}));
    let pane = otto.bounds(&[1])[0];
    otto.user_click(at(otto.control("top:bug"), 0.5, 0.5));
    let state = bug_report(&otto);
    let size = &state["bug"]["report"]["size"];
    let (w, h) = (size[0].as_f64().unwrap(), size[1].as_f64().unwrap());
    // A drag over the pane's top left leaves a box there, its comment typed next.
    let (from, to) = (at(pane, 0.1, 0.3), at(pane, 0.5, 0.6));
    let reply = otto.user_drag(from, to);
    let mark = &reply["bug"]["report"]["marks"][0];
    assert!(mark["rect"].is_array(), "no box from {from:?} to {to:?}: {}", reply["bug"]);
    let r = rect(&mark["rect"]);
    let near = |a: f64, b: f64| (a - b).abs() < 0.01;
    assert!(near(r[0], from[0] / w) && near(r[1], from[1] / h) && near(r[2], (to[0] - from[0]) / w), "{mark}");
    assert_eq!(reply["bug"]["report"]["typing"], mark["n"]);
    // A client's keys type nothing in it.
    otto.call(json!({"cmd": "key", "keys": "x"}));
    let reply = otto.user_key("t h e space r o w");
    assert_eq!(reply["bug"]["report"]["marks"][0]["comment"], "the row", "{}", reply["bug"]);
    // ↵ ends the comment; Whole app adds a mark; a client's click on it does not.
    assert!(otto.user_key("enter")["bug"]["report"]["typing"].is_null());
    let control = |id: &str| at(rect(&otto.call(json!({"cmd": "state"}))["bug"]["controls"][id]), 0.5, 0.5);
    let whole = control("bug:whole");
    otto.click(whole, 1);
    assert_eq!(otto.call(json!({"cmd": "state"}))["bug"]["report"]["marks"].as_array().unwrap().len(), 1);
    let reply = otto.user_click(whole);
    let marks = reply["bug"]["report"]["marks"].as_array().unwrap().clone();
    assert!(marks.len() == 2 && marks[1]["rect"].is_null(), "{marks:?}");
    // "Include app panes" is the user's toggle; nothing is blanked with no app pane.
    let apps = control("bug:apps");
    assert_eq!(otto.user_click(apps)["bug"]["report"]["apps"], true);
    assert_eq!(otto.call(json!({"cmd": "state"}))["bug"]["blanked"], json!([]));
    // A client's Esc cancels nothing; the user's ends the comment, then the report.
    otto.call(json!({"cmd": "key", "keys": "escape"}));
    assert!(!otto.call(json!({"cmd": "state"}))["bug"]["report"].is_null());
    otto.user_key("escape");
    otto.user_key("escape");
    assert!(otto.call(json!({"cmd": "state"}))["bug"]["report"].is_null());
}

#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn bug_send_files_a_task_in_a_new_worktree_with_a_brief_of_no_titles() {
    let (repo, home) = bug_setup("send");
    let root = support::temp(&format!("ottospace-e2e-bug-send-agent-{}", std::process::id()));
    let (bin, record) = (root.join("bin"), root.join("record"));
    std::fs::create_dir_all(&bin).unwrap();
    std::fs::create_dir_all(&record).unwrap();
    // The agents crate's stand-in, as `claude`: it records what it was given.
    let fake = Path::new(env!("CARGO_MANIFEST_DIR")).join("../ottospace-agents/tests/fakes/claude");
    std::fs::copy(&fake, bin.join("claude")).unwrap();
    let env = [
        ("OTTOSPACE_HOME", home.to_str().unwrap()),
        ("OTTOSPACE_AGENTS_DIR", bin.to_str().unwrap()),
        ("FAKE_DIR", record.to_str().unwrap()),
        ("GIT_CONFIG_GLOBAL", "/dev/null"),
        ("GIT_CONFIG_NOSYSTEM", "1"),
    ];
    let otto = Otto::launch_with("bug-send", &env);
    // A made-up title on screen: the brief holds none.
    otto.call(json!({"cmd": "split"}));
    otto.call(json!({"cmd": "task_new", "line": "Secretplan meeting"}));
    let pane = otto.bounds(&[1])[0];
    otto.user_key("cmd-ctrl-b");
    bug_report(&otto);
    otto.user_drag(at(pane, 0.1, 0.3), at(pane, 0.5, 0.6));
    otto.user_key("t a b s space f l i c k e r");
    // A client's ⌘↵ sends nothing.
    otto.call(json!({"cmd": "key", "keys": "cmd-enter"}));
    let tasks = |o: &Otto| o.call(json!({"cmd": "state"}))["state"]["tasks"]["list"].as_array().unwrap().clone();
    assert_eq!(tasks(&otto).len(), 1, "a client filed the report");
    otto.user_key("cmd-enter");
    let task = otto.wait_for("the bug's task", |o| tasks(o).into_iter().find(|t| t["title"] == "Bug: tabs flicker"));
    let file = task["materials"][0].as_str().expect("its brief's folder").to_string();
    let dir = home.join("materials").join(file.split('/').next().unwrap());
    // The worktree, made from the repository's HEAD on a new branch, not listed in Repos. Its
    // branch ends with the report's word, as its folder does: `<task>-<word>`.
    let tag = &dir.file_name().unwrap().to_str().unwrap().split_once('-').unwrap().1[..4];
    let worktree = home.canonicalize().unwrap().join(format!("worktrees/ottospace/bug-tabs-flicker-{tag}"));
    // The task is the repository's, then its worktree's once git has made it.
    let of = task["repo"].as_str().map(Path::new);
    assert!(of == Some(repo.as_path()) || of == Some(worktree.as_path()), "{task}");
    otto.wait_for("the worktree", |_| worktree.join(".git").is_file().then_some(()));
    // The agent starts there with the brief.
    let stdin = || std::fs::read_to_string(record.join("stdin")).unwrap_or_default();
    otto.wait_for("the agent", |_| stdin().contains("brief.md").then_some(()));
    let brief = std::fs::read_to_string(dir.join("brief.md")).unwrap();
    assert!(brief.contains("1. box over x") && brief.contains("\"tabs flicker\""), "{brief}");
    assert!(brief.contains("| build: ottospace") && brief.contains("<<<captured "), "{brief}");
    assert!(!brief.contains("Secretplan") && !brief.contains("meeting"), "a title in the brief: {brief}");
    let json = std::fs::read_to_string(dir.join("brief.json")).unwrap();
    assert!(json.contains("\"untrusted\": true") && !json.contains("Secretplan"), "{json}");
    // The picture and its marked copy, if the window could be pictured here.
    if brief.contains("report.annotated.png") {
        otto.wait_for("the pictures", |_| dir.join("report.annotated.png").is_file().then_some(()));
        assert!(std::fs::read(dir.join("report.png")).unwrap().starts_with(b"\x89PNG"));
    }
    assert!(otto.call(json!({"cmd": "state"}))["bug"]["report"].is_null());
}

/// A city's first picture rises (or, where a frame of the rise is too slow, fades in) over the
/// lattice it waited on, then no frame moves; under Reduce Motion it shows at once, no frame.
/// Covered and shown again, its picture (kept) shows at once: no render, no rise, no fade. The
/// state says how long the first picture took (`first_ms`).
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_city_rises_once_and_at_once_under_reduce_motion() {
    let root = support::temp(&format!("ottospace-e2e-city-fade-{}", std::process::id()));
    let app = root.join("app");
    std::fs::create_dir_all(app.join("src")).unwrap();
    git(&app, &["init", "-q"]);
    for (file, bytes) in [("src/main.rs", 900), ("src/lib.rs", 4000), ("README.md", 2000)] {
        std::fs::write(app.join(file), "x".repeat(bytes)).unwrap();
    }
    let app = app.canonicalize().unwrap().to_string_lossy().into_owned();
    for calm in [false, true] {
        let name = if calm { "city-fade-calm" } else { "city-fade" };
        let home = user_folder(name, &json!({"repos": [app], "restore_layout": false}).to_string());
        let mut env = vec![
            ("OTTOSPACE_HOME", home.to_str().unwrap()),
            ("OTTOSPACE_FEATURES", "code_city"),
            ("GIT_CONFIG_GLOBAL", "/dev/null"),
        ];
        if calm {
            env.push(("OTTOSPACE_REDUCE_MOTION", "1"));
        }
        let otto = Otto::launch_with(name, &env);
        let state = |o: &Otto| o.call(json!({"cmd": "state"}));
        let fades = |o: &Otto| {
            let counts = state(o)["counts"].clone();
            counts["city_fade_frames"].as_u64().unwrap() + counts["city_rise_frames"].as_u64().unwrap()
        };
        otto.call(json!({"cmd": "open_repo", "path": app}));
        otto.call(json!({"cmd": "close"}));
        let city = otto.wait_for("the city", |o| Some(state(o)["city"].clone()).filter(|c| !c["picture"].is_null()));
        assert!(city["first_ms"].as_u64().is_some(), "{city}");
        std::thread::sleep(Duration::from_millis(600));
        let after = fades(&otto);
        assert_eq!(after == 0, calm, "rises or fades in unless Reduce Motion: {after}");
        std::thread::sleep(Duration::from_millis(400));
        assert_eq!(fades(&otto), after, "no frame at rest");
        // A pane covers it, and goes: the kept picture, at once.
        let renders = state(&otto)["city"]["renders"].as_u64();
        otto.call(json!({"cmd": "split"}));
        otto.call(json!({"cmd": "close"}));
        otto.wait_for("the city again", |o| Some(state(o)["city"].clone()).filter(|c| !c["picture"].is_null()));
        std::thread::sleep(Duration::from_millis(400));
        assert_eq!((state(&otto)["city"]["renders"].as_u64(), fades(&otto)), (renders, after), "kept, no fade");
        drop(otto);
        let _ = std::fs::remove_dir_all(&home);
    }
    let _ = std::fs::remove_dir_all(&root);
}

/// The code city on every empty place with a folder (`code_city`). The owner's case: a Repos row
/// opens a terminal in its checkout, closed, the tab draws that checkout's city (and a worktree's
/// row its worktree's). An empty pane there draws it too; two empty panes of one size share one
/// picture, and the files are read once for both; a pane too small for a city keeps the lattice.
/// Home has no folder: no city.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn every_empty_place_with_a_folder_draws_its_city() {
    let root = support::temp(&format!("ottospace-e2e-city-places-{}", std::process::id()));
    let repos = root.join("repos");
    let app = repos.join("app");
    std::fs::create_dir_all(&app).unwrap();
    git(&app, &["init", "-q"]);
    for (file, bytes) in [("src/main.rs", 900), ("src/lib.rs", 4000), ("docs/a.md", 300), ("README.md", 2000)] {
        std::fs::create_dir_all(app.join(file).parent().unwrap()).unwrap();
        std::fs::write(app.join(file), "x".repeat(bytes)).unwrap();
    }
    git(&app, &["add", "-A"]);
    git(&app, &["-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "files"]);
    git(&app, &["worktree", "add", "-q", "-b", "fix", "../app-2"]);
    let repos = repos.canonicalize().unwrap();
    let path = |name: &str| repos.join(name).to_string_lossy().into_owned();
    let home = user_folder("city-places", &json!({"repos": [path("app")], "restore_layout": false}).to_string());
    let env = [
        ("OTTOSPACE_HOME", home.to_str().unwrap()),
        ("OTTOSPACE_FEATURES", "code_city"),
        ("GIT_CONFIG_GLOBAL", "/dev/null"),
    ];
    let otto = Otto::launch_with("city-places", &env);
    let city = |o: &Otto| o.call(json!({"cmd": "state"}))["city"].clone();
    let drawn = |o: &Otto, on: Value| {
        o.wait_for(&format!("a city on {on}"), |o| Some(city(o)).filter(|c| c["on"] == on && !c["picture"].is_null()))
    };
    assert_eq!(city(&otto), Value::Null, "Home: no folder, no city");
    otto.call(json!({"cmd": "section", "section": "repos"}));
    // The worktree's row, then the checkout's: a terminal there; closed, the tab is its city.
    for name in ["app-2", "app"] {
        otto.wait_for("the row", |o| o.control_opt(&format!("repo:{}", path(name))));
        otto.user_click(at(otto.control(&format!("repo:{}", path(name))), 0.5, 0.5));
        assert_eq!(city(&otto), Value::Null, "a terminal covers the tab");
        otto.user_key("cmd-w");
        let tab = drawn(&otto, json!("tab"));
        // Four files, two folders.
        assert_eq!((tab["places"].as_u64(), tab["groups"].as_u64()), (Some(6), Some(2)), "{name}: {tab}");
    }
    // An empty pane filling the tab, then two side by side: one picture for both, no read again.
    let reads = city(&otto)["reads"].as_u64();
    let one = pane_ids(&otto.call(json!({"cmd": "split", "kind": "empty"})))[0];
    let renders = drawn(&otto, json!({"pane": one}))["renders"].as_u64().unwrap();
    let reply = otto.call(json!({"cmd": "split", "kind": "empty"}));
    let two = *pane_ids(&reply).last().unwrap();
    let both = otto.bounds(&[one, two]);
    assert_eq!((both[0][2], both[0][3]), (both[1][2], both[1][3]), "two panes of one size");
    // The picture of their size, shared: one kept, as large as the pane in pixels. As numbers:
    // the picture's size is whole (`324`), a scaled bound a float (`324.0`), never equal as JSON.
    let size = |c: &Value| {
        let (b, scale) = (&c["bounds"], c["scale"].as_f64().unwrap_or(1.));
        let px = |v: &Value| (v.as_f64().unwrap_or(0.) * scale).round();
        let picture = c["picture"].as_array().map(|p| p.iter().map(|v| v.as_f64().unwrap_or(-1.)).collect::<Vec<_>>());
        picture == Some(vec![px(&b[2]), px(&b[3])])
    };
    let shared = otto.wait_for("one picture for both", |o| {
        // The shared picture reports either pane as its place.
        let on_either = |c: &Value| c["on"] == json!({"pane": one}) || c["on"] == json!({"pane": two});
        Some(city(o)).filter(|c| on_either(c) && c["pictures"] == json!(1) && size(c))
    });
    assert_eq!(shared["reads"].as_u64(), reads, "the files are read once per folder");
    assert!(shared["renders"].as_u64() > Some(renders), "drawn again at their size");
    // The first pane split down twice: too small for a city, its lattice.
    otto.call(json!({"cmd": "focus", "pane": one}));
    otto.call(json!({"cmd": "split", "kind": "empty", "axis": "down"}));
    otto.call(json!({"cmd": "focus", "pane": one}));
    otto.call(json!({"cmd": "split", "kind": "empty", "axis": "down"}));
    let small = otto.wait_for("a small pane", |o| {
        Some(city(o)).filter(|c| c["small"].as_array().is_some_and(|small| small.contains(&json!({"pane": one}))))
    });
    assert!(otto.bounds(&[one])[0][3] < 220., "{small}");
    drop(otto);
    let _ = std::fs::remove_dir_all(&root);
    let _ = std::fs::remove_dir_all(&home);
}

/// The code city's camera (`code_city`), moved by the user's pointer only: a middle drag pans,
/// the wheel's lines zoom (clamped), a left drag past a click turns it (pitch clamped), Esc
/// during a drag puts it back, the Reset view button (only on a moved camera, and only the
/// user's click) brings back the fitted view. Each move renders the
/// picture again; at rest no frame is asked for. A client's drag moves nothing.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn the_users_pointer_moves_the_citys_camera() {
    let root = support::temp(&format!("ottospace-e2e-city-camera-{}", std::process::id()));
    let app = root.join("repos/app");
    std::fs::create_dir_all(&app).unwrap();
    git(&app, &["init", "-q"]);
    for (file, bytes) in [("src/main.rs", 900), ("src/lib.rs", 4000), ("docs/a.md", 300), ("README.md", 2000)] {
        std::fs::create_dir_all(app.join(file).parent().unwrap()).unwrap();
        std::fs::write(app.join(file), "x".repeat(bytes)).unwrap();
    }
    let app = app.canonicalize().unwrap();
    let home = user_folder("city-camera", &json!({"repos": [app], "restore_layout": false}).to_string());
    let env = [
        ("OTTOSPACE_HOME", home.to_str().unwrap()),
        ("OTTOSPACE_FEATURES", "code_city"),
        ("GIT_CONFIG_GLOBAL", "/dev/null"),
    ];
    let otto = Otto::launch_with("city-camera", &env);
    otto.call(json!({"cmd": "open_repo", "path": app}));
    otto.call(json!({"cmd": "close"}));
    let city = |o: &Otto| o.call(json!({"cmd": "state"}))["city"].clone();
    let first = otto.wait_for("a city", |o| Some(city(o)).filter(|c| !c["picture"].is_null()));
    let b: Vec<f64> = first["bounds"].as_array().unwrap().iter().map(|v| v.as_f64().unwrap()).collect();
    // Under the hints, on the city.
    let p = [b[0] + b[2] / 2., b[1] + b[3] * 0.8];
    let view = |o: &Otto| city(o)["view"].clone();
    let fitted = view(&otto);
    let num = |v: &Value, key: &str| v[key].as_f64().unwrap();
    let mouse = |action: &str, at: [f64; 2], button: &str, user: bool| {
        let mut event = json!({"cmd": "mouse", "action": action, "x": at[0], "y": at[1], "button": button});
        if user {
            event["as"] = json!("user");
        }
        otto.call(event);
    };
    let drag = |button: &str, by: [f64; 2], user: bool| {
        mouse("down", p, button, user);
        for i in 1..=6 {
            mouse("move", [p[0] + by[0] * i as f64 / 6., p[1] + by[1] * i as f64 / 6.], button, user);
        }
        mouse("up", [p[0] + by[0], p[1] + by[1]], button, user);
    };
    // A client's middle drag: refused, the camera stays.
    drag("middle", [80., 0.], false);
    assert_eq!(view(&otto), fitted, "a client's drag");
    // The user's wheel over the hints is theirs: the camera stays.
    let hint = otto.control("home:terminal");
    otto.call(json!({"cmd": "mouse", "action": "wheel", "x": hint[0] + 4., "y": hint[1] + 4., "dy": 3, "as": "user"}));
    assert_eq!(view(&otto), fitted, "a wheel over the hints");
    // The user's: the city moves with the pointer, and is drawn again.
    let renders = city(&otto)["renders"].as_u64().unwrap();
    drag("middle", [80., 0.], true);
    let panned = view(&otto);
    assert!(panned["pan"] != fitted["pan"] && panned["zoom"] == fitted["zoom"], "{panned}");
    assert_eq!(city(&otto)["grabbed"], json!(false));
    otto.wait_for("the picture again", |o| (city(o)["renders"].as_u64() > Some(renders)).then_some(()));
    // The wheel's lines zoom in, about the pointer, no nearer than the clamp.
    otto.call(json!({"cmd": "mouse", "action": "wheel", "x": p[0], "y": p[1], "dy": 3, "as": "user"}));
    let near = num(&view(&otto), "zoom");
    assert!(near < 1., "{near}");
    for _ in 0..12 {
        otto.call(json!({"cmd": "mouse", "action": "wheel", "x": p[0], "y": p[1], "dy": 10, "as": "user"}));
    }
    assert_eq!(num(&view(&otto), "zoom"), 0.05_f32 as f64);
    // A left drag turns it; far down, the pitch stops at its clamp. A press that hardly moves
    // is a click: nothing turns.
    let before = view(&otto);
    drag("left", [3., 0.], true);
    assert_eq!(view(&otto), before, "a click");
    drag("left", [60., 0.], true);
    let turned = view(&otto);
    assert!(num(&turned, "yaw") != num(&before, "yaw"), "{turned}");
    // 120 points (48°, past the clamp), inside the window: a move off it reaches no element.
    drag("left", [0., 120.], true);
    assert_eq!(num(&view(&otto), "pitch"), 80.);
    // Esc during a drag: back where it began.
    let before = view(&otto);
    mouse("down", p, "left", true);
    mouse("move", [p[0] + 40., p[1]], "left", true);
    mouse("move", [p[0] + 90., p[1] - 30.], "left", true);
    assert!(view(&otto) != before && city(&otto)["grabbed"] == json!(true));
    otto.user_key("escape");
    mouse("up", [p[0] + 90., p[1] - 30.], "left", true);
    assert_eq!(view(&otto), before, "Esc puts it back");
    // Moved: its Reset view button. A client's click on it does nothing; the user's brings back
    // the fitted view, eased, and the button goes.
    let reset = otto.control("city:reset:tab");
    let centre = [reset[0] + reset[2] / 2., reset[1] + reset[3] / 2.];
    for action in ["down", "up"] {
        otto.call(json!({"cmd": "mouse", "action": action, "x": centre[0], "y": centre[1]}));
    }
    assert!(view(&otto) != fitted, "a client's click");
    for action in ["down", "up"] {
        otto.call(json!({"cmd": "mouse", "action": action, "x": centre[0], "y": centre[1], "as": "user"}));
    }
    assert_eq!(view(&otto), fitted, "reset");
    assert!(otto.control_opt("city:reset:tab").is_none(), "no button on a fitted camera");
    // At rest: no frame asked for.
    std::thread::sleep(Duration::from_millis(600));
    let frames = otto.call(json!({"cmd": "state"}))["counts"]["city_frames"].clone();
    std::thread::sleep(Duration::from_millis(600));
    assert_eq!(otto.call(json!({"cmd": "state"}))["counts"]["city_frames"], frames);
    drop(otto);
    let _ = std::fs::remove_dir_all(&root);
    let _ = std::fs::remove_dir_all(&home);
}

/// The city's names (`city.names`) are placed by `city_labels`: apart, clear of the key hints,
/// inside the picture, again after a zoom. The user's pointer on a folder's ground outlines its
/// top face and hangs its label by its near edge or the pointer; on a building, a beam a share of
/// the picture tall, its label right beside its dot.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_citys_names_stay_apart_and_a_hovered_folder_is_outlined() {
    let root = support::temp(&format!("ottospace-e2e-city-names-{}", std::process::id()));
    let app = root.join("repos/app");
    std::fs::create_dir_all(&app).unwrap();
    git(&app, &["init", "-q"]);
    for dir in ["src/model", "src/view", "src/net", "docs", "tests"] {
        for i in 0..6 {
            let file = app.join(format!("{dir}/f{i}.rs"));
            std::fs::create_dir_all(file.parent().unwrap()).unwrap();
            std::fs::write(file, "x".repeat(400 + 900 * i)).unwrap();
        }
    }
    let app = app.canonicalize().unwrap();
    let home = user_folder("city-names", &json!({"repos": [app], "restore_layout": false}).to_string());
    let env = [
        ("OTTOSPACE_HOME", home.to_str().unwrap()),
        ("OTTOSPACE_FEATURES", "code_city"),
        ("GIT_CONFIG_GLOBAL", "/dev/null"),
    ];
    let otto = Otto::launch_with("city-names", &env);
    otto.call(json!({"cmd": "open_repo", "path": app}));
    otto.call(json!({"cmd": "close"}));
    // The drawer folded: at CI's window the city gets the whole tab, room for the walls' names.
    otto.call(json!({"cmd": "key", "keys": "cmd-shift-r", "as": "user"}));
    let city = |o: &Otto| o.call(json!({"cmd": "state"}))["city"].clone();
    // Standing (a rise's frames name nothing) and named.
    let named = |c: &Value| c["names"].as_array().is_some_and(|n| !n.is_empty()) && !c["spots"]["folder"].is_null();
    let first = otto.wait_for("a named city", |o| Some(city(o)).filter(named));
    let numbers = |v: &Value| v.as_array().unwrap().iter().map(|n| n.as_f64().unwrap()).collect::<Vec<_>>();
    let b = numbers(&first["bounds"]);
    let hints: Vec<[f64; 4]> =
        otto.controls().into_iter().filter(|(id, _)| id.starts_with("home:")).map(|(_, r)| r).collect();
    let apart =
        |a: &[f64], b: &[f64]| a[0] + a[2] <= b[0] || b[0] + b[2] <= a[0] || a[1] + a[3] <= b[1] || b[1] + b[3] <= a[1];
    let within = |r: &[f64]| {
        r[0] >= b[0] - 0.5 && r[1] >= b[1] - 0.5 && r[0] + r[2] <= b[0] + b[2] + 0.5 && r[1] + r[3] <= b[1] + b[3] + 0.5
    };
    let check = |c: &Value| {
        let names = c["names"].as_array().unwrap();
        assert!(!names.is_empty() && names.len() <= 50 && c["labels"].as_u64() == Some(names.len() as u64), "{c}");
        let rects: Vec<Vec<f64>> = names.iter().map(|n| numbers(&n["rect"])).collect();
        for (i, r) in rects.iter().enumerate() {
            assert!(within(r), "{r:?} in {b:?}");
            assert!(hints.iter().all(|h| apart(r, h)), "{r:?} over the hints {hints:?}");
            assert!(rects[i + 1..].iter().all(|o| apart(r, o)), "{r:?} over another: {rects:?}");
        }
        assert!(!c.to_string().contains("MODEL") && !c.to_string().contains("f1.rs"), "no name in the state: {c}");
        rects
    };
    let fitted = check(&first);
    assert!(first["names"].as_array().unwrap().iter().any(|n| n["tier"] == "wall"), "{first}");
    // The user's pointer on a folder's own ground (`spots`), then over a grid of the city: the
    // building whose beam is longest (one under the hints is lowered).
    let hover = |x: f64, y: f64| {
        otto.call(json!({"cmd": "mouse", "action": "move", "x": x, "y": y, "as": "user"}));
        city(&otto)["hovered"].clone()
    };
    let at = numbers(&first["spots"]["folder"]);
    let folder = hover(at[0], at[1]);
    assert_eq!(folder["file"], json!(false), "{first}");
    let length = |h: &Value| h["beam"].as_array().map_or(0., |b| b[1].as_f64().unwrap() - b[3].as_f64().unwrap());
    let mut file: Option<Value> = None;
    for row in 1..8 {
        for col in 1..10 {
            let h = hover(b[0] + b[2] * col as f64 / 10., b[1] + b[3] * row as f64 / 8.);
            if h["file"] == json!(true) && file.as_ref().is_none_or(|f| length(&h) > length(f)) {
                file = Some(h);
            }
        }
    }
    let outline: Vec<Vec<f64>> = folder["outline"].as_array().unwrap().iter().map(numbers).collect();
    assert_eq!((outline.len(), &folder["beam"]), (4, &Value::Null), "{folder}");
    let label = numbers(&folder["beacon"]);
    assert!(within(&label) && hints.iter().all(|h| apart(&label, h)), "{label:?}");
    // By its near edge (the lowest corner), else by the pointer: never in the middle of the city.
    let near = outline.iter().max_by(|a, b| a[1].total_cmp(&b[1])).unwrap();
    let by = |p: &[f64]| {
        (label[0] - 40. ..=label[0] + label[2] + 40.).contains(&p[0])
            && (label[1] - 40. ..=label[1] + label[3] + 40.).contains(&p[1])
    };
    assert!(by(near) || by(&at), "{label:?} by {near:?} or {at:?}");
    let file = file.expect("a building under the pointer");
    let (beam, label) = (numbers(&file["beam"]), numbers(&file["beacon"]));
    // Long, or lowered to just under the hints (the city sits below them: #403).
    let under = hints.iter().map(|h| h[1] + h[3]).fold(f64::MIN, f64::max);
    let lowered = beam[1] - beam[3] >= 12. && beam[3] >= under;
    let long = beam[1] - beam[3] >= 0.2 * b[3] || beam[3] <= b[1] + 0.06 * b[3] || lowered;
    assert!(long, "a beam to see: {beam:?} in {b:?}, the hints' foot {under}");
    let gap = if label[0] >= beam[2] { label[0] - beam[2] } else { beam[2] - label[0] - label[2] };
    assert!((0. ..=8.).contains(&gap) && (label[1] + label[3] / 2. - beam[3]).abs() < 1., "{label:?} by {beam:?}");
    // Zoomed in: names placed again, still apart.
    let renders = city(&otto)["renders"].as_u64();
    let p = [b[0] + b[2] / 2., b[1] + b[3] * 0.8];
    otto.call(json!({"cmd": "mouse", "action": "wheel", "x": p[0], "y": p[1], "dy": 4, "as": "user"}));
    // Drawn again and named again (a paint may land before the render's state is read; the
    // wheel's own pictures are half size and unnamed, #437).
    let zoomed = otto.wait_for("names placed again", |o| {
        Some(city(o)).filter(|c| c["renders"].as_u64() > renders && named(c) && c["names"] != first["names"])
    });
    assert_ne!(check(&zoomed), fitted, "names follow the camera");
    drop(otto);
    let _ = std::fs::remove_dir_all(&root);
    let _ = std::fs::remove_dir_all(&home);
}

/// Shell lines as activity in the code city: while `cd <checkout> && ls src/ui` runs, the agent
/// stands over that folder's plinth, its cone on it, pulsing; while `git status` (no path) runs, it
/// hovers, its icon pulsing; its turn over, it is gone and no frame pulses. Under Reduce Motion
/// nothing pulses.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_shell_line_in_the_city_stands_its_agent_over_the_path_it_names_and_pulses() {
    const S: &str = r#""session_id":"8f14e45f-ceea-467f-a8d3-0242ac130003""#;
    for calm in [false, true] {
        let mut extra = vec![("OTTOSPACE_FEATURES", "code_city"), ("GIT_CONFIG_GLOBAL", "/dev/null")];
        extra.extend(calm.then_some(("OTTOSPACE_REDUCE_MOTION", "1")));
        let name = if calm { "city-shell-calm" } else { "city-shell" };
        let (root, _, env) = native_setup(name, &[], &extra);
        let app = root.join("repos/app");
        git(&app, &["init", "-q"]);
        for (file, bytes) in
            [("src/main.rs", 3000), ("src/ui/mod.rs", 9000), ("src/ui/view.rs", 4000), ("docs/a.md", 500)]
        {
            let path = app.join(file);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(path, "x".repeat(bytes)).unwrap();
        }
        let app = app.canonicalize().unwrap();
        let bash = |id: &str, line: String| {
            let call = json!({"type": "tool_use", "id": id, "name": "Bash", "input": {"command": line}});
            format!(r#"{{"type":"assistant",{S},"parent_tool_use_id":null,"message":{{"content":[{call}]}}}}"#)
        };
        let result = |id: &str| {
            let r = json!({"type": "tool_result", "tool_use_id": id, "content": "ok", "is_error": false});
            format!(r#"{{"type":"user",{S},"parent_tool_use_id":null,"message":{{"content":[{r}]}}}}"#)
        };
        let init =
            format!(r#"{{"type":"system","subtype":"init",{S},"model":"claude-opus-5-5","permissionMode":"default"}}"#);
        let done = r#"{"type":"result","subtype":"success","is_error":false,"total_cost_usd":0.01}"#;
        let lines = [
            init,
            bash("b1", format!("cd {} && ls src/ui", app.display())),
            r#"{"_sleep":4}"#.into(),
            result("b1"),
            bash("b2", format!("cd {} && git status", app.display())),
            r#"{"_sleep":4}"#.into(),
            result("b2"),
            done.into(),
        ];
        std::fs::write(root.join("fixtures/turn1.jsonl"), lines.join("\n") + "\n").unwrap();
        let otto = launch_env(name, &env);
        otto.call(json!({"cmd": "task_new", "line": "first >app"}));
        otto.call(json!({"cmd": "section", "section": "tasks"}));
        otto.start_task(1);
        otto.call(json!({"cmd": "open_space", "space": {"kind": "task", "id": 1}}));
        let agent = |o: &Otto| o.call(json!({"cmd": "state"}))["city"]["agents"][0].clone();
        let pulses = |o: &Otto| o.call(json!({"cmd": "state"}))["counts"]["city_pulse_frames"].as_u64().unwrap();
        // Over the folder's plinth, its cone on it.
        let over = otto.wait_for("over src/ui", |o| Some(agent(o)).filter(|a| a["cone"] == json!(true)));
        assert_eq!(over["pulsing"], json!(!calm), "{over}");
        // No path named: hovering, its icon pulsing.
        let hovers = otto.wait_for("hovering", |o| {
            Some(agent(o)).filter(|a| a["cone"] == json!(false) && (calm || a["pulsing"] == json!(true)))
        });
        assert_eq!(hovers["pulsing"], json!(!calm), "{hovers}");
        let before = pulses(&otto);
        std::thread::sleep(Duration::from_millis(400));
        assert!(if calm { pulses(&otto) == 0 } else { pulses(&otto) > before }, "pulse frames while busy");
        // The turn over: no agent, no frame.
        otto.wait_for("the turn over", |o| Some(agent(o)).filter(Value::is_null));
        std::thread::sleep(Duration::from_millis(300));
        let rest = pulses(&otto);
        std::thread::sleep(Duration::from_millis(600));
        assert_eq!(pulses(&otto), rest, "no frames at rest");
        drop(otto);
        let _ = std::fs::remove_dir_all(&root);
    }
}

/// The code city (flag `code_city`): a task's empty tab draws its checkout's files as a 3D
/// picture rendered on the GPU, where the lattice was, as large as the tab in pixels. The file
/// the agent reads is lit, and only it, its agent's icon over it; an ignored file is no building;
/// nothing is read or rendered again while nothing changes; the state has counts and rectangles,
/// never a name. The user's click on the icon goes to its task, a client's does not. With
/// no GPU (`OTTOSPACE_CITY_NO_GPU`), the lattice, and the state says why. With the flag off, no
/// city and no read.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_tasks_empty_tab_draws_its_checkout_as_a_city_and_lights_the_file_its_agent_reads() {
    const S: &str = r#""session_id":"8f14e45f-ceea-467f-a8d3-0242ac130003""#;
    let setup = |name: &str, features: &str, gpu: bool| {
        // None of the user's git settings: an ignore rule of theirs would hide a made-up file.
        let mut extra = vec![("OTTOSPACE_FEATURES", features), ("GIT_CONFIG_GLOBAL", "/dev/null")];
        if !gpu {
            extra.push(("OTTOSPACE_CITY_NO_GPU", "1"));
        }
        let (root, _, env) = native_setup(name, &[], &extra);
        // A real, empty repository with made-up files: seven it lists, one it ignores.
        let app = root.join("repos/app");
        git(&app, &["init", "-q"]);
        let files = [
            ("src/auth.rs", 5000),
            ("src/main.rs", 300),
            ("src/ui/mod.rs", 9000),
            ("docs/a.md", 100),
            ("docs/b.md", 100),
            ("README.md", 2500),
            (".gitignore", 0),
            ("target/out.bin", 70_000),
        ];
        for (file, bytes) in files {
            let path = app.join(file);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            let text = if file == ".gitignore" { "target\n".to_string() } else { "x".repeat(bytes) };
            std::fs::write(path, text).unwrap();
        }
        // The agent reads src/auth.rs, and the read does not end.
        let read = json!({"type": "tool_use", "id": "toolu_r", "name": "Read", "input": {"file_path": app.join("src/auth.rs")}});
        let init =
            format!(r#"{{"type":"system","subtype":"init",{S},"model":"claude-opus-5-5","permissionMode":"default"}}"#);
        let call = format!(r#"{{"type":"assistant",{S},"parent_tool_use_id":null,"message":{{"content":[{read}]}}}}"#);
        std::fs::write(root.join("fixtures/turn1.jsonl"), format!("{init}\n{call}\n")).unwrap();
        let otto = launch_env(name, &env);
        otto.call(json!({"cmd": "task_new", "line": "first >app"}));
        otto.call(json!({"cmd": "section", "section": "tasks"}));
        otto.start_task(1);
        otto.call(json!({"cmd": "open_space", "space": {"kind": "task", "id": 1}}));
        (root, otto)
    };
    let city = |o: &Otto| o.call(json!({"cmd": "state"}))["city"].clone();

    let (root, otto) = setup("city", "code_city", true);
    let lit = otto.wait_for("a lit building", |o| {
        Some(city(o)).filter(|city| city["lit"].as_array().is_some_and(|lit| !lit.is_empty()))
    });
    // Seven files and three folders (src, src/ui, docs): the ignored one is no building.
    assert_eq!((lit["places"].as_u64(), lit["groups"].as_u64()), (Some(10), Some(3)), "{lit}");
    // The picture is the tab's floor in pixels: never scaled.
    let numbers = |v: &Value| v.as_array().unwrap().iter().map(|n| n.as_f64().unwrap()).collect::<Vec<_>>();
    let (bounds, scale, picture) = (numbers(&lit["bounds"]), lit["scale"].as_f64().unwrap(), numbers(&lit["picture"]));
    assert_eq!(picture, [(bounds[2] * scale).round(), (bounds[3] * scale).round()], "{lit}");
    assert_eq!(lit["failed"], Value::Null, "{lit}");
    // One building is lit, inside the picture, and the state names no file.
    let rects = lit["lit"].as_array().unwrap();
    assert_eq!(rects.len(), 1, "{lit}");
    let (r, a) = (numbers(&rects[0]), bounds);
    assert!(r[2] >= 1. && r[3] >= 1., "{lit}");
    assert!(r[0] >= a[0] && r[1] >= a[1] && r[0] + r[2] <= a[0] + a[2] && r[1] + r[3] <= a[1] + a[3], "{r:?} in {a:?}");
    assert!(!lit.to_string().contains("auth") && !lit.to_string().contains("src"), "{lit}");
    // At rest nothing is read again, however often the state is asked.
    // (The read the lit file asked for, if the first came before the agent's call, lands first.)
    std::thread::sleep(Duration::from_millis(1500));
    let (reads, renders) = (city(&otto)["reads"].as_u64(), city(&otto)["renders"].as_u64());
    assert_eq!(otto.call(json!({"cmd": "state"}))["counts"]["city_reads"].as_u64(), reads);
    for _ in 0..5 {
        std::thread::sleep(Duration::from_millis(300));
        let now = city(&otto);
        assert_eq!((now["reads"].as_u64(), now["renders"].as_u64(), &now["lit"]), (reads, renders, &lit["lit"]));
    }
    // The lit building's steady beam rises from its top.
    let top = numbers(&city(&otto)["lit_tops"][0]);
    let rises = |beam: &[f64]| {
        let (dx, dy) = (beam[2] - beam[0], beam[1] - beam[3]);
        (beam[0] - top[0]).abs() < 1. && (beam[1] - top[1]).abs() < 1. && dy > 8. && dx.abs() < dy
    };
    let beams = city(&otto)["lit_beams"].clone();
    assert!(beams.as_array().is_some_and(|b| b.len() == 1 && rises(&numbers(&b[0]))), "{beams} from {top:?}");
    // The user's pointer on the lit building's top: its beam, from the top up, with a label beside
    // its dot, a file's, lit, clear of the hints; it fades in; nothing rendered again. A client's
    // pointer, and the user's over the hints: no beam.
    let frames = || otto.call(json!({"cmd": "state"}))["counts"]["city_beam_frames"].as_u64().unwrap();
    let before = frames();
    let point = |x: f64, y: f64, user: bool| {
        let mut move_to = json!({"cmd": "mouse", "action": "move", "x": x, "y": y});
        if user {
            move_to["as"] = json!("user");
        }
        otto.call(move_to);
        city(&otto)["hovered"].clone()
    };
    let hovered = point(top[0], top[1] + 1., true);
    assert_eq!((&hovered["file"], &hovered["lit"]), (&json!(true), &json!(true)), "{hovered}");
    assert!(rises(&numbers(&hovered["beam"])), "{hovered} from {top:?}");
    assert!(frames() > before, "the beam fades in");
    assert_eq!(city(&otto)["lit_beams"], beams, "its steady beam stays under the hovered one");
    let hints = otto.control("home:terminal");
    let label = numbers(&hovered["beacon"]);
    let apart =
        |a: &[f64], b: &[f64]| a[0] + a[2] <= b[0] || b[0] + b[2] <= a[0] || a[1] + a[3] <= b[1] || b[1] + b[3] <= a[1];
    assert!(apart(&label, &hints), "{label:?} over {hints:?}");
    let dot = numbers(&hovered["beam"]);
    assert!((label[1] + label[3] / 2. - dot[3]).abs() < 1., "the label beside the dot: {label:?} {dot:?}");
    assert_eq!(city(&otto)["renders"].as_u64(), renders, "hover renders nothing");
    assert_eq!(point(hints[0] + 4., hints[1] + 4., true), Value::Null, "over a hint, the hint wins");
    assert_eq!(point(top[0], top[1] + 1., false), Value::Null, "a client's pointer shows none");
    // The agent floats over the file it reads: its icon over the lit building's top, its cone
    // on it, alone in its fan; at rest no frame glides it. The user's pointer on it names it,
    // and wins over the building under it.
    let agents = city(&otto)["agents"].clone();
    let icon = numbers(&agents[0]["rect"]);
    let one = (agents.as_array().map(Vec::len), &agents[0]["task"], &agents[0]["cone"], &agents[0]["fan"]);
    assert_eq!(one, (Some(1), &json!(1), &json!(true), &json!([0, 1])), "{agents}");
    // On its beam (vertical in the world, slanted in perspective), above the top.
    let centre = (icon[0] + icon[2] / 2., icon[1] + icon[3] / 2.);
    let beam = numbers(&beams[0]);
    let x = beam[0] + (centre.1 - beam[1]) / (beam[3] - beam[1]) * (beam[2] - beam[0]);
    assert!((centre.0 - x).abs() < 2. && centre.1 < top[1], "{icon:?} on {beam:?} over {top:?}");
    assert!(apart(&icon, &hints), "{icon:?} over {hints:?}");
    let glides = || otto.call(json!({"cmd": "state"}))["counts"]["city_agent_frames"].as_u64().unwrap();
    let still = glides();
    std::thread::sleep(Duration::from_millis(600));
    assert_eq!(glides(), still, "no frames at rest");
    assert_eq!(point(centre.0, centre.1, true), Value::Null, "the icon wins over the building");
    assert_eq!(city(&otto)["agents"][0]["hovered"], json!(true));
    // A pane in the tab covers the floor: no city. Closed: the same city, the same place.
    otto.call(json!({"cmd": "split"}));
    assert_eq!(city(&otto), Value::Null);
    otto.call(json!({"cmd": "close"}));
    // Its picture is made again for the tab (none is kept for a place gone): wait for it.
    let again = otto.wait_for("the city back", |o| Some(city(o)).filter(|city| !city["picture"].is_null()));
    assert_eq!(again["lit"], lit["lit"]);
    // In a workspace on the checkout the task's agent floats too: a client's click on it stays,
    // the user's own goes to its task. The user folds the drawer (⌘⇧R: a client moves no space
    // while their keys are in the chat) and makes the workspace (from Home a client's terminal
    // would go to the task's space, the one selected last).
    otto.call(json!({"cmd": "key", "keys": "cmd-shift-r", "as": "user"}));
    otto.user_click(at(otto.control("top:new_workspace"), 0.5, 0.5));
    // Listed resolved: the temp dir is behind a symlink.
    otto.call(json!({"cmd": "open_repo", "path": root.join("repos/app").canonicalize().unwrap()}));
    otto.call(json!({"cmd": "close"}));
    let icon = otto.wait_for("the agent over the workspace's city", |o| {
        Some(city(o)["agents"][0]["rect"].clone()).filter(|rect| !rect.is_null())
    });
    let icon = numbers(&icon);
    let click = |user: bool| {
        for action in ["down", "up"] {
            let mut press =
                json!({"cmd": "mouse", "action": action, "x": icon[0] + icon[2] / 2., "y": icon[1] + icon[3] / 2.});
            if user {
                press["as"] = json!("user");
            }
            otto.call(press);
        }
        selected_space(&otto)["of"].clone()
    };
    assert_eq!(click(false)["kind"], "workbook", "a client's click goes nowhere");
    assert_eq!(click(true), json!({"kind": "task", "id": 1}));
    drop(otto);
    let _ = std::fs::remove_dir_all(&root);

    // No GPU: the files are read, no picture is made, and the lattice is the floor.
    let (root, otto) = setup("city-no-gpu", "code_city", false);
    let failed = otto.wait_for("no picture", |o| Some(city(o)).filter(|city| !city["failed"].is_null()));
    assert_eq!((&failed["failed"], &failed["picture"]), (&json!("no GPU (test)"), &Value::Null), "{failed}");
    assert!(otto.call(json!({"cmd": "state"}))["home_drawn"]["lattice_builds"].as_u64() > Some(0));
    drop(otto);
    let _ = std::fs::remove_dir_all(&root);

    // The flag off: the lattice, and no read.
    let (root, otto) = setup("city-off", "", true);
    std::thread::sleep(Duration::from_secs(2));
    let state = otto.call(json!({"cmd": "state"}));
    assert_eq!(
        (&state["city"], state["counts"]["city_reads"].as_u64()),
        (&Value::Null, Some(0)),
        "{}",
        state["counts"]
    );
    assert!(otto.call(json!({"cmd": "state"}))["home_drawn"]["lattice_builds"].as_u64() > Some(0));
    drop(otto);
    let _ = std::fs::remove_dir_all(&root);
}

#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn the_projects_section_lists_a_made_up_folder_only_once_opened_and_newest_first() {
    use std::time::SystemTime;
    // Made-up projects: a folder with a note, two lone notes of set ages, and what is no project.
    let dir = support::temp(&format!("ottospace-e2e-projects-{}", std::process::id()));
    std::fs::create_dir_all(dir.join("beta-hiring")).unwrap();
    std::fs::write(dir.join("beta-hiring/README.md"), "# Beta hiring\n").unwrap();
    let days_ago = |days: u64| SystemTime::now() - Duration::from_secs(days * 86_400);
    for (name, days) in [("alpha-launch.md", 3), ("gamma.md", 10)] {
        std::fs::write(dir.join(name), format!("# {name}\n")).unwrap();
        let file = std::fs::File::options().write(true).open(dir.join(name)).unwrap();
        file.set_modified(days_ago(days)).unwrap();
    }
    std::fs::write(dir.join(".hidden.md"), "# Hidden").unwrap();
    std::fs::write(dir.join("notes.txt"), "not a project").unwrap();
    let settings = json!({"projects_dir": dir, "repos": [], "restore_layout": false, "sessions": false});
    let home = user_folder("projects", &settings.to_string());
    let otto = Otto::launch_with("projects-1", &[("OTTOSPACE_HOME", home.to_str().unwrap()), PROJECTS]);

    // Set, but nothing read before the section opens.
    let bar = otto.call(json!({"cmd": "state"}))["projects_bar"].clone();
    assert_eq!(bar, json!({"on": true, "rows": []}));
    otto.call(json!({"cmd": "section", "section": "projects"}));
    let rows = otto.wait_for("three projects drawn", |o| {
        let rows = o.call(json!({"cmd": "state"}))["projects_bar"]["rows"].as_array()?.clone();
        (rows.len() == 3 && rows.iter().all(|row| !row["row"].is_null())).then_some(rows)
    });
    // Newest first: the folder (changed now), then the notes by age. No title or path is given.
    let kinds: Vec<(bool, bool, bool)> = rows
        .iter()
        .map(|r| (r["file"].as_bool().unwrap(), r["note"].as_bool().unwrap(), r["placed"].as_bool().unwrap()))
        .collect();
    assert_eq!(kinds, [(false, true, false), (true, true, false), (true, true, false)]);
    let modified: Vec<u64> = rows.iter().map(|r| r["modified"].as_u64().unwrap()).collect();
    assert!(modified.windows(2).all(|w| w[0] > w[1]), "{modified:?}");
    let tops: Vec<f64> = rows.iter().map(|r| rect(&r["row"])[1]).collect();
    assert!(tops.windows(2).all(|w| w[0] < w[1]), "rows drawn in order: {tops:?}");
    let state = otto.call(json!({"cmd": "state"}));
    assert!(!state.to_string().contains("Beta hiring") && !state.to_string().contains("alpha-launch"));
    drop(otto);

    // No folder of its own: no settings, no section, nothing read.
    let otto = Otto::launch_with("projects-2", &[PROJECTS]);
    let reply = otto.call(json!({"cmd": "section", "section": "projects"}));
    let shown = (&reply["projects_bar"], &reply["state"]["sidebar"]);
    assert_eq!(shown, (&json!({"on": false, "rows": []}), &json!(null)));
    drop(otto);
    let _ = std::fs::remove_dir_all(&home);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_project_dragged_up_stays_placed_and_a_click_opens_its_note_read_only() {
    use std::time::SystemTime;
    // Made-up projects: a folder with no note, and two notes of set ages.
    let dir = support::temp(&format!("ottospace-e2e-projects-open-{}", std::process::id()));
    std::fs::create_dir_all(dir.join("hiring")).unwrap();
    let days_ago = |days: u64| SystemTime::now() - Duration::from_secs(days * 86_400);
    for (name, days) in [("launch.md", 3), ("spike.md", 10)] {
        std::fs::write(dir.join(name), format!("# {name}\n")).unwrap();
        let file = std::fs::File::options().write(true).open(dir.join(name)).unwrap();
        file.set_modified(days_ago(days)).unwrap();
    }
    let settings = json!({"projects_dir": dir, "repos": [], "restore_layout": false, "sessions": false});
    let home = user_folder("projects-open", &settings.to_string());
    let launch = |n: &str| Otto::launch_with(n, &[("OTTOSPACE_HOME", home.to_str().unwrap()), PROJECTS]);
    let rows = |o: &Otto| {
        o.wait_for("three projects drawn", |o| {
            let rows = o.call(json!({"cmd": "state"}))["projects_bar"]["rows"].as_array()?.clone();
            (rows.len() == 3 && rows.iter().all(|row| !row["row"].is_null())).then_some(rows)
        })
    };
    let otto = launch("projects-open-1");
    otto.call(json!({"cmd": "section", "section": "projects"}));
    let before = rows(&otto);
    let spike = before[2]["modified"].clone();
    // A client's drag places nothing; the user's drag of the oldest to the top places it.
    otto.drag(at(rect(&before[2]["row"]), 0.5, 0.5), at(rect(&before[0]["row"]), 0.5, 0.2));
    assert!(rows(&otto).iter().all(|row| row["placed"] == false));
    otto.user_drag(at(rect(&before[2]["row"]), 0.5, 0.5), at(rect(&before[0]["row"]), 0.5, 0.2));
    let after = rows(&otto);
    assert_eq!((&after[0]["placed"], &after[0]["modified"]), (&json!(true), &spike));
    let kept: Value = serde_json::from_str(&std::fs::read_to_string(home.join("projects.json")).unwrap()).unwrap();
    assert_eq!(kept["placed"].as_array().map(Vec::len), Some(1));
    // A client's click opens nothing (the note's path would be in the state); the user's opens
    // its note in a viewer; the folder with no note opens nothing.
    let none = after.iter().position(|row| row["note"] == false).unwrap();
    let panes = |reply: &Value| reply["state"]["panes"].as_array().unwrap().len();
    let count = panes(&otto.call(json!({"cmd": "state"})));
    assert_eq!(panes(&otto.click(at(rect(&after[0]["row"]), 0.5, 0.5), 1)), count);
    assert_eq!(panes(&otto.user_click(at(rect(&after[none]["row"]), 0.5, 0.5))), count);
    let reply = otto.user_click(at(rect(&after[0]["row"]), 0.5, 0.5));
    let path = dir.join("spike.md").to_string_lossy().into_owned();
    assert!(
        reply["state"]["panes"].as_array().unwrap().iter().any(|p| p["kind"] == json!({"type": "file", "path": path}))
    );
    assert_eq!(panes(&reply), count + 1);
    drop(otto);

    // Kept across a restart.
    let otto = launch("projects-open-2");
    otto.call(json!({"cmd": "section", "section": "projects"}));
    assert_eq!(rows(&otto)[0]["placed"], true);
    drop(otto);
    let _ = std::fs::remove_dir_all(&home);
    let _ = std::fs::remove_dir_all(&dir);
}

/// Zoom-out (`zoom_out`): ⌘⇧\ shows the space's tabs as tiles on a grid with room between, in the
/// panes area, at CI's window and the default. Arrows select, ↵ or a click goes in, Esc and ⌘⇧\
/// go back to the tab it opened on; sneak labels the tiles. Only the user zooms. Under Reduce
/// Motion no frame is asked for.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn zoomed_out_the_tabs_are_tiles_on_a_grid_and_the_keys_go_in_and_back() {
    for size in ["1024x674", "1400x900"] {
        let env =
            [("OTTOSPACE_FEATURES", "zoom_out"), ("OTTOSPACE_REDUCE_MOTION", "1"), ("OTTOSPACE_E2E_WINDOW", size)];
        let otto = Otto::launch_with(&format!("zoom-{size}"), &env);
        // Four tabs of one terminal each; the first on show.
        otto.call(json!({"cmd": "split"}));
        for _ in 1..4 {
            otto.call(json!({"cmd": "new_tab"}));
            otto.call(json!({"cmd": "split"}));
        }
        let state = otto.call(json!({"cmd": "select_tab", "index": 0}));
        let tabs: Vec<u64> = (0..4).map(|at| state["state"]["tabs"][at]["id"].as_u64().unwrap()).collect();
        let pane = state["state"]["focused"].as_u64().unwrap();
        // The panes area: the one pane, its header included (`bounds` starts under it).
        let drawn = otto.drawn();
        let (body, header) = (rect(&drawn["bounds"][pane.to_string()]), rect(&drawn["headers"][pane.to_string()]));
        let area = [body[0], header[1], body[2], body[1] + body[3] - header[1]];
        let shown = |s: &Value| s["state"]["tabs"][s["state"]["active"].as_u64().unwrap() as usize]["id"].clone();
        otto.call(json!({"cmd": "type", "pane": pane, "text": "sleep 30\r"}));
        // A client's ⌘⇧\ is refused: the overview covers the user's work.
        let refused = otto.call(json!({"cmd": "key", "keys": "cmd-|"}));
        assert_eq!((&refused["state"]["zoom"], &refused["zoom_tiles"]), (&Value::Null, &Value::Null), "{size}");
        let zoomed = otto.user_key("cmd-|");
        assert_eq!(zoomed["state"]["zoom"], json!({"from": tabs[0], "selected": tabs[0]}), "{size}");
        let drawn = otto.drawn();
        let tiles: Vec<[f64; 4]> = tabs.iter().map(|id| rect(&drawn["zoom_tiles"][id.to_string()])).collect();
        // A 2×2 grid inside the panes area, each tile its shape, room between.
        for (i, t) in tiles.iter().enumerate() {
            let inside = t[0] >= area[0] - 1. && t[1] >= area[1] - 1.;
            assert!(
                inside && t[0] + t[2] <= area[0] + area[2] + 1. && t[1] + t[3] <= area[1] + area[3] + 1.,
                "{size}: {t:?} in {area:?}"
            );
            assert!((t[2] / t[3] - area[2] / area[3]).abs() < 0.05, "{size}: tile {i} {t:?} keeps {area:?}'s shape");
            assert!(t[2] > area[2] / 4., "{size}: tile {i} {t:?} is not a speck");
        }
        assert!(
            (tiles[0][1] - tiles[1][1]).abs() < 1. && tiles[1][0] >= tiles[0][0] + tiles[0][2] + 20.,
            "{size}: {tiles:?}"
        );
        assert!(
            (tiles[0][0] - tiles[2][0]).abs() < 1. && tiles[2][1] >= tiles[0][1] + tiles[0][3] + 20.,
            "{size}: {tiles:?}"
        );
        // Nothing moves at rest, and under Reduce Motion nothing moved at all.
        assert_eq!(drawn["counts"]["zoom_frames"], 0, "{size}");
        // Sneak labels each tile.
        let labelled = otto.control(&format!("zoom-tile:{}", tabs[3]));
        assert!(
            (labelled[0] - tiles[3][0]).abs() < 2. && (labelled[1] - tiles[3][1]).abs() < 2.,
            "{size}: {labelled:?}"
        );
        // → ↓ ↵: into the fourth tab.
        otto.user_key("right");
        let moved = otto.user_key("down");
        assert_eq!(moved["state"]["zoom"]["selected"], tabs[3], "{size}");
        let typed = otto.user_key("x");
        assert_eq!(typed["state"]["zoom"]["selected"], tabs[3], "{size}: a letter types nowhere");
        // Nor ⌃C: the program in the first tab runs on.
        otto.user_key("ctrl-c");
        std::thread::sleep(Duration::from_millis(300));
        let text = otto.call(json!({"cmd": "capture", "pane": pane}))["text"].to_string();
        assert!(!text.contains("^C"), "{size}: ⌃C reached the terminal: {text}");
        let entered = otto.user_key("enter");
        assert_eq!((&entered["state"]["zoom"], shown(&entered)), (&Value::Null, json!(tabs[3])), "{size}");
        assert_eq!(otto.drawn()["zoom_tiles"], Value::Null, "{size}");
        // Out again, a move, and Esc: back to the tab it opened on.
        otto.user_key("cmd-|");
        otto.user_key("left");
        let back = otto.user_key("escape");
        assert_eq!((&back["state"]["zoom"], shown(&back)), (&Value::Null, json!(tabs[3])), "{size}");
        // A client's click on a tile is refused; the user's goes into its tab.
        otto.user_key("cmd-|");
        let tile = rect(&otto.drawn()["zoom_tiles"][tabs[1].to_string()]);
        let theirs = otto.click(at(tile, 0.5, 0.5), 1);
        assert_eq!(shown(&theirs), json!(tabs[3]), "{size}");
        let clicked = otto.user_click(at(tile, 0.5, 0.5));
        assert_eq!((&clicked["state"]["zoom"], shown(&clicked)), (&Value::Null, json!(tabs[1])), "{size}");
        // ⌘⇧\ twice: back where it was.
        otto.user_key("cmd-|");
        let toggled = otto.user_key("cmd-|");
        assert_eq!((&toggled["state"]["zoom"], shown(&toggled)), (&Value::Null, json!(tabs[1])), "{size}");
        assert_eq!(otto.drawn()["counts"]["zoom_frames"], 0, "{size}");
    }
}

/// The zoom plays both ways and never holds up a key: the model has moved before it starts, the
/// zoom back in is drawn only, and at rest no frame is asked for.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn the_zoom_plays_both_ways_and_asks_for_no_frame_at_rest() {
    let otto = Otto::launch_with("zoom-motion", &[("OTTOSPACE_FEATURES", "zoom_out")]);
    otto.call(json!({"cmd": "split"}));
    otto.call(json!({"cmd": "new_tab"}));
    otto.call(json!({"cmd": "split"}));
    let zoomed = otto.user_key("cmd-|");
    assert!(zoomed["state"]["zoom"].is_object(), "open at once: {}", zoomed["state"]["zoom"]);
    let frames = |o: &Otto| o.drawn()["counts"]["zoom_frames"].as_u64().unwrap_or(0);
    // It plays, then rests: two looks a moment apart ask for no frame between them.
    let rest = otto.wait_for("the zoom out at rest", |o| {
        let was = frames(o);
        std::thread::sleep(Duration::from_millis(400));
        (was > 0 && frames(o) == was).then_some(was)
    });
    // ↵ at once: in the tab, while the tiles still play back, drawn only.
    let entered = otto.user_key("enter");
    assert!(entered["state"]["zoom"].is_null());
    otto.wait_for("the zoom back at rest", |o| {
        let drawn = o.drawn();
        (drawn["zoom_tiles"].is_null() && frames(o) > rest).then_some(())
    });
    let at_rest = frames(&otto);
    std::thread::sleep(Duration::from_millis(400));
    assert_eq!(frames(&otto), at_rest, "a frame asked for at rest");
}

/// Decisions filed from any source (`decision_sources`): a made-up Slack thread filed over the
/// socket waits to be sorted; the same key is its next revision; its words are given only by
/// `decision`, labelled untrusted, never in the state; it is kept (0600) and comes back after a
/// restart; a malformed one, one past a cap and any with the flag off are refused, saying why.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn a_filed_decision_waits_to_be_sorted_updates_by_key_and_keeps_its_words_out_of_the_state() {
    use std::os::unix::fs::PermissionsExt;
    let settings = json!({"repos": [], "restore_layout": false, "sessions": false});
    let home = user_folder("decision-sources", &settings.to_string());
    let launch = |n: &str| Otto::launch_with(n, &[("OTTOSPACE_HOME", home.to_str().unwrap()), DECISION_SOURCES]);
    let otto = launch("decisions-filed-1");
    let key = "slack:C0MADEUP:1763500000.000100";
    let words = "MADEUPWORDS can we flip it before 5?";
    let filing = json!({
        "cmd": "decision_file", "source": "slack", "key": key,
        "summary": "Asked in #made-up-rollout whether the flag can flip",
        "question": "Reply to the rollout thread today, or hand it over?",
        "options": [{"label": "Draft a reply", "act": {"draft_reply": {"text": "Made-up draft."}}}],
        "recommend": 0,
        "evidence": [{"kind": "quote", "text": words, "provenance": {"source": "slack", "who": "person"}}],
        "claims": {"person_waits": true}
    });
    let filed = otto.call(filing.clone());
    assert_eq!(
        (&filed["revision"], &filed["status"], &filed["triage"]),
        (&json!(1), &json!("open"), &json!("pending"))
    );
    let id = filed["id"].as_u64().unwrap();
    let state = otto.call(json!({"cmd": "state"}));
    assert_eq!((&state["filed"]["open"], &state["filed"]["to_sort"]), (&json!(1), &json!(1)), "{}", state["filed"]);
    assert_eq!(
        (state["filed"]["rows"][0]["id"].as_u64(), &state["filed"]["rows"][0]["evidence"]),
        (Some(id), &json!(1))
    );
    assert!(!state.to_string().contains("MADEUPWORDS"), "others' words are never in the state");
    // The same key again: its next revision, never another decision; the same twice, no change.
    let mut again = filing.clone();
    again["why"] = json!("the asker is blocked");
    let updated = otto.call(again.clone());
    assert_eq!((updated["id"].as_u64(), &updated["revision"]), (Some(id), &json!(2)));
    assert_eq!(otto.call(again)["revision"], 2);
    // Its words, labelled.
    let read = otto.call(json!({"cmd": "decision", "id": id}));
    let decision = &read["decision"];
    assert_eq!((&decision["untrusted"], &decision["evidence"][0]["text"]), (&json!(true), &json!(words)));
    // Malformed: refused, saying why.
    let refused = |change: &dyn Fn(&mut Value)| {
        let mut bad = filing.clone();
        change(&mut bad);
        let reply = otto.raw(&bad.to_string());
        assert_eq!(reply["ok"], false, "{bad}");
        reply["error"].as_str().unwrap_or_default().to_string()
    };
    assert!(refused(&|f| f["key"] = json!("../x")).contains("key"));
    assert!(
        refused(&|f| f["key"] = json!("slack:general:1.0")).contains("slack:<channel>:<ts>"),
        "its source's format"
    );
    assert!(refused(&|f| f["source"] = json!("terminal_session")).contains("ottospace's own"));
    let http = json!({"open_link": {"url": "http://example.com/"}});
    assert!(refused(&|f| f["options"][0]["act"] = http.clone()).contains("https"));
    assert!(refused(&|f| f["evidence"][0]["at"] = json!({"path": "/etc/hosts"})).contains("listed repository"));
    // Kept on disk, the user's alone.
    let file = home.join("decisions").join(format!("{id}.json"));
    assert_eq!(std::fs::metadata(&file).unwrap().permissions().mode() & 0o777, 0o600);
    // Withdrawn: closed; a second withdraw finds nothing open.
    let withdrawn = otto.call(json!({"cmd": "decision_withdraw", "source": "slack", "key": key}));
    assert_eq!(withdrawn["filed"]["rows"][0]["status"], "withdrawn", "{withdrawn}");
    assert_eq!(otto.raw(&json!({"cmd": "decision_withdraw", "source": "slack", "key": key}).to_string())["ok"], false);
    // Twenty open from one source at most.
    for n in 0..20 {
        let key = format!("slack:C{n}:1.0");
        otto.call(json!({"cmd": "decision_file", "source": "slack", "key": key, "question": "Made up?"}));
    }
    let past = otto.raw(
        &json!({"cmd": "decision_file", "source": "slack", "key": "slack:C20:1.0", "question": "Made up?"}).to_string(),
    );
    assert!(past["error"].as_str().unwrap_or_default().contains("20 open from slack"), "{past}");
    drop(otto);

    // Kept across a restart.
    let otto = launch("decisions-filed-2");
    let state = otto.call(json!({"cmd": "state"}));
    let rows = state["filed"]["rows"].as_array().unwrap();
    assert_eq!(rows.len(), 21);
    assert!(rows.iter().any(|row| row["id"].as_u64() == Some(id) && row["status"] == "withdrawn"));
    drop(otto);
    let _ = std::fs::remove_dir_all(&home);

    // The flag off: refused, and nothing in the state.
    let otto = Otto::launch("decisions-filed-off");
    assert_eq!(otto.raw(&filing.to_string())["error"], "feature off: decision_sources");
    assert_eq!(otto.call(json!({"cmd": "state"}))["filed"], Value::Null);
}

/// Triage (`decision_sources`, in Decisions): made-up items filed over the socket wait as one
/// card, "Sort 3 new items", after any agent's question. Only the user opens it and sorts: one key
/// an item (T now, N not mine, D dismiss), Z takes the last back, P lets a channel skip triage.
/// The status bar says how many wait to be sorted.
#[test]
#[ignore = "opens a window; run with `cargo e2e`"]
fn filed_decisions_are_sorted_one_key_each_by_the_user_alone() {
    let otto = Otto::launch_with("triage", &[("OTTOSPACE_FEATURES", "decisions,decision_sources")]);
    let mut ids = Vec::new();
    for (source, key) in [("slack", "slack:C0MADEUP:1.0"), ("slack", "slack:C0MADEUP:2.0"), ("jira", "jira:ABC-1")] {
        let filed = otto.call(json!({
            "cmd": "decision_file", "source": source, "key": key,
            "summary": format!("Made-up item {key}"), "question": "Take it this week?"
        }));
        ids.push(filed["id"].as_u64().unwrap());
    }
    assert_eq!(otto.call(json!({"cmd": "state"}))["filed"]["to_sort"], 3);
    let item = |reply: &Value| reply["state"]["decisions"]["sort"]["item"].clone();
    let row = |reply: &Value, id: u64| {
        let rows = reply["filed"]["rows"].as_array().cloned().unwrap_or_default();
        rows.into_iter().find(|row| row["id"].as_u64() == Some(id)).unwrap_or_default()
    };
    // A client opens nothing and sorts nothing.
    assert_eq!(otto.call(json!({"cmd": "key", "keys": "cmd-j"}))["state"]["decisions"], Value::Null);
    let opened = otto.user_key("cmd-j");
    assert_eq!((item(&opened), &opened["state"]["decisions"]["task"]), (Value::Null, &Value::Null), "{opened}");
    assert_eq!(item(&otto.call(json!({"cmd": "key", "keys": "enter"}))), Value::Null);
    // The user's ↵: the first filed first. T takes it now; Z takes that back.
    assert_eq!(item(&otto.user_key("enter")), json!(ids[0]));
    let now = otto.user_key("t");
    assert_eq!((&row(&now, ids[0])["triage"], item(&now)), (&json!("sorted"), json!(ids[1])));
    let back = otto.user_key("z");
    assert_eq!((&row(&back, ids[0])["triage"], item(&back)), (&json!("pending"), json!(ids[0])));
    assert_eq!(row(&otto.user_key("n"), ids[0])["status"], "not_mine");
    // P: the channel skips triage from now.
    let promoted = otto.user_key("p");
    assert_eq!((&row(&promoted, ids[1])["triage"], &promoted["filed"]["trusted"]), (&json!("skipped"), &json!(1)));
    // D on the last: "All sorted" (Z could take it back); Esc closes Decisions.
    let done = otto.user_key("d");
    let sort = &done["state"]["decisions"]["sort"];
    assert_eq!(
        (&row(&done, ids[2])["status"], &sort["item"], &sort["left"]),
        (&json!("dismissed"), &Value::Null, &json!(0))
    );
    assert_eq!(done["filed"]["to_sort"], 0);
    assert_eq!(otto.user_key("escape")["state"]["decisions"], Value::Null);
}
